const AiProfilePanel: React.FC<{ isOpen: boolean; onClose: () => void; }> = ({ isOpen, onClose }) => {
    const { settings, updateSettings } = useSettings();
    const [newEquipment, setNewEquipment] = useState('');
    const { userProfile } = settings;

    const age = useMemo(() => {
        if (!userProfile?.birthDate) return null;
        try {
            const birthDate = new Date(userProfile.birthDate);
            const today = new Date();
            let age = today.getFullYear() - birthDate.getFullYear();
            const m = today.getMonth() - birthDate.getMonth();
            if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
                age--;
            }
            return age > 0 ? age : null;
        } catch {
            return null;
        }
    }, [userProfile?.birthDate]);

    const handleProfileUpdate = (field: keyof NonNullable<typeof userProfile>, value: any) => {
        updateSettings({
            userProfile: {
                ...userProfile,
                [field]: value,
            },
        });
    };

    const handleAddEquipment = () => {
        const trimmedName = newEquipment.trim();
        if (trimmedName === '') return;
        const currentEquipment = userProfile?.equipment || [];
        if (currentEquipment.some(e => e.name.toLowerCase() === trimmedName.toLowerCase())) return;

        handleProfileUpdate('equipment', [...currentEquipment, { name: trimmedName, available: true }]);
        setNewEquipment('');
    };

    const handleRemoveEquipment = (nameToRemove: string) => {
        handleProfileUpdate('equipment', (userProfile?.equipment || []).filter(e => e.name !== nameToRemove));
    };

    const handleToggleEquipment = (nameToToggle: string) => {
        handleProfileUpdate('equipment', (userProfile?.equipment || []).map(e => 
            e.name === nameToToggle ? { ...e, available: !e.available } : e
        ));
    };

    const FitnessButton: React.FC<{level: 'beginner' | 'intermediate' | 'advanced'}> = ({ level }) => {
        const isActive = userProfile?.fitnessLevel === level;
        return (
            <button 
                onClick={() => handleProfileUpdate('fitnessLevel', level)}
                className={`flex-1 py-2 text-sm font-semibold rounded-md transition-colors ${isActive ? 'bg-blue-600 text-white' : 'bg-gray-600 hover:bg-gray-500'}`}
            >
                {level.charAt(0).toUpperCase() + level.slice(1)}
            </button>
        );
    };

    return (
        <>
            <div 
                className={`fixed inset-0 bg-black/50 z-[101] transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} 
                onClick={onClose}
            />
            <div 
                className={`fixed top-0 right-0 h-full w-full max-w-sm bg-gray-800 shadow-2xl z-[102] transform transition-transform duration-300 flex flex-col ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}
                dir="rtl"
            >
                <div className="flex justify-between items-center p-4 border-b border-gray-700 shrink-0">
                    <h3 className="text-xl font-bold text-white">הפרופיל שלי</h3>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-700">
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
                <div className="p-4 space-y-6 overflow-y-auto flex-grow">
                    <div>
                        <label className="text-sm font-semibold text-gray-300">תאריך לידה</label>
                        <div className="flex items-center gap-4 mt-1">
                            <input 
                                type="date"
                                value={userProfile?.birthDate || ''}
                                onChange={e => handleProfileUpdate('birthDate', e.target.value)}
                                className="bg-gray-700 p-2 rounded-md text-white w-full"
                            />
                            {age && <span className="text-lg font-bold text-white shrink-0">{age}</span>}
                        </div>
                    </div>
                    <div>
                        <label className="text-sm font-semibold text-gray-300">רמת כושר</label>
                        <div className="flex gap-2 mt-1">
                            <FitnessButton level="beginner" />
                            <FitnessButton level="intermediate" />
                            <FitnessButton level="advanced" />
                        </div>
                    </div>
                     <div>
                        <label className="text-sm font-semibold text-gray-300">הציוד שלי</label>
                        <div className="flex gap-2 mt-1">
                            <input 
                                type="text"
                                value={newEquipment}
                                onChange={e => setNewEquipment(e.target.value)}
                                onKeyPress={e => e.key === 'Enter' && handleAddEquipment()}
                                placeholder="הוסף ציוד..."
                                className="flex-grow bg-gray-700 p-2 rounded-md text-white"
                            />
                            <button onClick={handleAddEquipment} className="px-4 py-2 bg-blue-600 rounded-md font-semibold hover:bg-blue-700">+</button>
                        </div>
                        <div className="mt-3 space-y-2 max-h-60 overflow-y-auto pr-2">
                            {(userProfile?.equipment || []).map(item => (
                                <div key={item.name} className="flex items-center bg-gray-700/50 p-2 rounded-md">
                                    <input 
                                        type="checkbox"
                                        id={`equip-${item.name}`}
                                        checked={item.available}
                                        onChange={() => handleToggleEquipment(item.name)}
                                        className="w-5 h-5 bg-gray-600 border-gray-500 text-blue-500 rounded focus:ring-blue-500"
                                    />
                                    <label htmlFor={`equip-${item.name}`} className="flex-grow mx-3 text-white truncate cursor-pointer">{item.name}</label>
                                    <button onClick={() => handleRemoveEquipment(item.name)} className="p-1 text-gray-400 hover:text-red-500">
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
};


const AiPlannerModal: React.FC<{
    onClose: () => void;
}> = ({ onClose }) => {
    type ChatPart = { text: string; isPlanLink?: boolean; planName?: string };
    type ChatMessage = { role: 'user' | 'model'; parts: ChatPart[] };

    const { importPlan } = useWorkout();
    const { settings } = useSettings();
    const AI_CHAT_HISTORY_KEY = 'sportsClockAiChatHistory_v2';

    const [messages, setMessages] = useState<ChatMessage[]>(() => {
        try {
            const saved = localStorage.getItem(AI_CHAT_HISTORY_KEY);
            return saved ? JSON.parse(saved) : [];
        } catch { return []; }
    });
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        localStorage.setItem(AI_CHAT_HISTORY_KEY, JSON.stringify(messages));
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    useEffect(() => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            const scrollHeight = textarea.scrollHeight;

            const computedStyle = getComputedStyle(textarea);
            const lineHeight = parseFloat(computedStyle.lineHeight) || 24; // Fallback
            const paddingTop = parseFloat(computedStyle.paddingTop);
            const paddingBottom = parseFloat(computedStyle.paddingBottom);
            const maxHeight = (lineHeight * 5) + paddingTop + paddingBottom;

            textarea.style.height = `${Math.min(scrollHeight, maxHeight)}px`;
            textarea.style.overflowY = scrollHeight > maxHeight ? 'auto' : 'hidden';
        }
    }, [input]);

    const handleNewChat = () => {
        setMessages([]);
        localStorage.removeItem(AI_CHAT_HISTORY_KEY);
    };

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: input }] };
        const newMessages = [...messages, userMessage];
        setMessages(newMessages);
        setInput('');
        setIsLoading(true);

        let profileContext = '';
        if (settings.userProfile) {
            const { userProfile } = settings;
            const profileParts = [];
            if (userProfile.birthDate) {
                const birthDate = new Date(userProfile.birthDate);
                const age = new Date().getFullYear() - birthDate.getFullYear();
                if (age > 0 && age < 120) profileParts.push(`Age: ${age}`);
            }
            if (userProfile.fitnessLevel) {
                profileParts.push(`Fitness Level: ${userProfile.fitnessLevel}`);
            }
            const availableEquipment = userProfile.equipment?.filter(e => e.available).map(e => e.name);
            if (availableEquipment && availableEquipment.length > 0) {
                profileParts.push(`Available Equipment: ${availableEquipment.join(', ')}`);
            }
            if (profileParts.length > 0) {
                profileContext = profileParts.join('; ');
            }
        }

        try {
            const responseText = await generateWorkoutPlan(messages, input, profileContext);

            // The service now returns a user-friendly error string, prefixed with "Error:".
            if (responseText.startsWith('Error: ')) {
                const userFriendlyMessage = responseText.substring('Error: '.length);
                setMessages(prev => [...prev, { role: 'model', parts: [{ text: userFriendlyMessage }] }]);
                return; // Stop further processing
            }


            // --- Success Path ---
            const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
            const match = responseText.match(jsonRegex);
            const conversationalText = responseText.replace(jsonRegex, '').trim();

            let finalMessages = [...newMessages];

            if (conversationalText) {
                finalMessages.push({ role: 'model', parts: [{ text: conversationalText }]});
            }

            if (match && match[1]) {
                try {
                    const planJson = JSON.parse(match[1]);
                    planJson.isSmartPlan = true;
                    planJson.color = '#a855f7';

                    await importPlan(planJson, 'ai');

                    finalMessages.push({ role: 'model', parts: [{ text: '', isPlanLink: true, planName: planJson.name }]});

                } catch (e) {
                    console.error("Failed to parse AI-generated JSON:", e);
                    finalMessages.push({ role: 'model', parts: [{ text: "I tried to generate a plan, but there was an error in the format. Could you please clarify your request? The full response is below for debugging:\n\n" + responseText }] });
                }
            } else if (!conversationalText) {
                // If there's no conversational text and no JSON, it's probably just a text response.
                 finalMessages.push({ role: 'model', parts: [{ text: responseText }]});
            }

            setMessages(finalMessages);

        } catch (error) {
            console.error("AI Planner error:", error);
            const errorMessage = error instanceof Error ? error.message : "Sorry, something went wrong.";
            setMessages([...newMessages, { role: 'model', parts: [{ text: errorMessage }] }]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-gray-900/90 z-[100] flex flex-col p-4" aria-modal="true" role="dialog">
            <AiProfilePanel isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} />
             <div className="flex justify-between items-center mb-4 text-white">
                <button onClick={() => setIsProfileOpen(true)} title="הפרופיל שלי" className="p-2 rounded-full hover:bg-gray-700">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-6-3a2 2 0 11-4 0 2 2 0 014 0zm-2 4a5 5 0 00-4.546 2.916A5.986 5.986 0 0010 16a5.986 5.986 0 004.546-2.084A5 5 0 0010 11z" clipRule="evenodd" />
                    </svg>
                </button>
                <h2 className="text-xl font-bold flex items-center gap-2">✨ AI Workout Planner</h2>
                <div className="flex items-center gap-2">
                    <button onClick={handleNewChat} title="Start a new chat" className="p-2 rounded-full hover:bg-gray-700">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 110 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" /></svg>
                    </button>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-700">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
            </div>
            <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
                 {messages.length === 0 && (
                    <div className="text-center text-gray-400 p-8" dir="rtl">
                        <p className="text-lg">ברוכים הבאים לממתכנן האימונים החכם!</p>
                        <p className="mt-2">תאר את האימון שברצונך לבנות. לדוגמה:</p>
                        <em className="block mt-2">"צור לי תוכנית אימון למתחילים באורך 20 דקות לכל הגוף."</em>
                    </div>
                )}
                {messages.map((msg, index) => (
                    <div key={index} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-prose p-3 rounded-lg select-text ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                            {msg.parts.map((part, partIndex) => 
                                part.isPlanLink ? (
                                    <div key={partIndex} dir="auto">
                                        <p>הוספתי את תוכנית "{part.planName}" לרשימה שלך.</p>
                                        <button onClick={onClose} className="mt-2 font-bold text-blue-300 hover:text-blue-200 underline">
                                            הצג תוכנית
                                        </button>
                                    </div>
                                ) : (
                                    <p key={partIndex} className="whitespace-pre-wrap select-text" dir="auto">{part.text}</p>
                                )
                            )}
                        </div>
                    </div>
                ))}
                {isLoading && (
                     <div className="flex justify-start">
                        <div className="max-w-sm p-3 rounded-lg bg-gray-700 text-gray-200">
                            <div className="flex items-center gap-3">
                                <div className="flex items-center gap-2">
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0s'}}></div>
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></div>
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                                </div>
                                <span className="text-sm italic text-gray-400">בונה לך את האימון המושלם, כמה רגעים...</span>
                            </div>
                        </div>
                    </div>
                )}
                 <div ref={messagesEndRef} />
            </div>
            <div className="flex gap-2">
                <textarea
                    ref={textareaRef}
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        // Support multi-line on mobile/desktop. 
                        // Desktop: Enter to send, Shift+Enter for newline.
                        // Mobile/Small screen: Let Enter be a newline (standard behavioral fallback for mobile textareas),
                        // and use the explicit Send button for sending.
                        if (e.key === 'Enter' && !e.shiftKey && window.innerWidth > 768) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder="תאר את האימון הרצוי..."
                    className="flex-grow bg-gray-800 text-white p-3 rounded-lg focus:outline-none focus:ring-2 ring-blue-500 resize-none"
                    dir="rtl"
                    disabled={isLoading}
                />
                <button onClick={handleSend} disabled={isLoading || !input.trim()} className="px-6 py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 disabled:bg-gray-600 disabled:cursor-not-allowed">
                    Send
                </button>
            </div>
        </div>
    );
};


export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void; }> = ({ isOpen, setIsOpen }) => {
  const [isPinned, setIsPinned] = useState(false);
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null | string>(null);
  const [view, setView] = useState<'list' | 'editor' | 'log'>('list');
  const [confirmDeletePlanId, setConfirmDeletePlanId] = useState<string | null>(null);
  const [exerciseToInspect, setExerciseToInspect] = useState<string | null>(null);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);
  const { activeWorkout, plans, deletePlan } = useWorkout();
  const { settings, updateSettings } = useSettings();
  const modalMutedApp = useRef(false);
  const [isAiPlannerOpen, setIsAiPlannerOpen] = useState(false);

  // Mute app sounds when the exercise modal is visible and restore on close.
  useEffect(() => {
    if (isModalVisible) {
      // Modal is opening.
      if (!settings.isMuted) {
        modalMutedApp.current = true;
        updateSettings({ isMuted: true });
      }
    } else {
      // Modal is closing.
      if (modalMutedApp.current) {
        modalMutedApp.current = false;
        updateSettings({ isMuted: false });
      }
    }
  }, [isModalVisible, settings.isMuted, updateSettings]);

  const planToDelete = useMemo(() => {
    return plans.find(p => p.id === confirmDeletePlanId) || null;
  }, [confirmDeletePlanId, plans]);

  const planToEdit = useMemo(() => {
    if(editingPlan === null) return null;
    if(typeof editingPlan === 'string' && editingPlan === '_warmup_') {
        return {
            id: '_warmup_',
            name: 'חימום',
            steps: settings.warmupSteps,
            color: '#f97316', // Orange for warm-up
            version: 2,
        } as WorkoutPlan
    }
    return editingPlan as WorkoutPlan;
  }, [editingPlan, settings.warmupSteps]);

  // Touch handlers for swipe-to-close gesture
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const handleTouchStart = (e: React.TouchEvent) => {
      touchEndX.current = null;
      touchStartX.current = e.touches[0].clientX;
  };
  const handleTouchMove = (e: React.TouchEvent) => {
      touchEndX.current = e.touches[0].clientX;
  };
  const handleTouchEnd = () => {
      if (!touchStartX.current || !touchEndX.current) return;
      const distance = touchEndX.current - touchStartX.current;
      // Swipe left to close, respecting the pin
      if (distance < -minSwipeDistance && !isPinned) {
          setIsOpen(false);
      }
      touchStartX.current = null;
      touchEndX.current = null;
  };

  useEffect(() => {
    if (!isOpen) {
        setIsPinned(false); // Unpin when manually closed
        setTimeout(() => {
             setView('list');
             setEditingPlan(null);
        }, 500); 
    }
  }, [isOpen]);

  const handleCreateNew = () => {
      localStorage.removeItem(EDITOR_STORAGE_KEY);
      setEditingPlan(null);
      setView('editor');
  };

  const handleSelectPlan = (plan: WorkoutPlan | string) => {
      localStorage.removeItem(EDITOR_STORAGE_KEY);
      setEditingPlan(plan);
      setView('editor');
  };

  const handleBack = () => {
      setView('list');
      setEditingPlan(null);
  };

  const handleConfirmDelete = () => {
    if (confirmDeletePlanId) {
        deletePlan(confirmDeletePlanId);
        setConfirmDeletePlanId(null);
    }
  };

  const handleInspectExercise = (exerciseName: string) => {
    if (isModalVisible && exerciseToInspect === exerciseName) {
        return;
    }
    setExerciseToInspect(exerciseName);
    setIsModalVisible(true);
  };

  const handleCloseModal = () => {
    setIsModalVisible(false);
  };

  useEffect(() => {
      if(activeWorkout && !isPinned) {
          setIsOpen(false);
      }
  }, [activeWorkout, isPinned]);


  return (
    <>
      <div className="absolute top-4 left-4 menu-container group">
        <button 
          onClick={() => setIsOpen(!isOpen)} 
          aria-label="Open workout planner"
          className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none opacity-0 group-hover:opacity-100"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>
        </button>
      </div>

      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40"
          onClick={() => !isPinned && setIsOpen(false)}
        ></div>
      )}

      {planToDelete && (
          <ConfirmDeleteModal 
              planName={planToDelete.name}
              onConfirm={handleConfirmDelete}
              onCancel={() => setConfirmDeletePlanId(null)}
          />
      )}

      <ExerciseInfoModal 
          exerciseName={exerciseToInspect}
          onClose={handleCloseModal}
          isVisible={isModalVisible}
      />

      {infoPlan && <WorkoutInfoModal plan={infoPlan} onClose={() => setInfoPlan(null)} />}

      {isAiPlannerOpen && <AiPlannerModal onClose={() => setIsAiPlannerOpen(false)} />}

      <div 
        className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/80 backdrop-blur-md shadow-2xl z-50 transform transition-all ease-in-out ${isOpen ? 'duration-500' : 'duration-[1500ms]'} ${isOpen ? 'translate-x-0 opacity-100' : '-translate-x-full opacity-0 pointer-events-none'}`}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        >
          <div className="p-6 overflow-y-auto h-full">
            {view === 'list' && (
                <PlanList 
                    onSelectPlan={handleSelectPlan} 
                    onCreateNew={handleCreateNew} 
                    onInitiateDelete={setConfirmDeletePlanId}
                    onShowLog={() => setView('log')}
                    onInspectExercise={handleInspectExercise}
                    onShowInfo={setInfoPlan}
                    isPinned={isPinned}
                    onTogglePin={() => setIsPinned(!isPinned)}
                    onOpenAiPlanner={() => setIsAiPlannerOpen(true)}
                />
            )}
            {view === 'editor' && (
                <PlanEditor 
                    plan={planToEdit} 
                    onBack={handleBack} 
                    isWarmupEditor={typeof editingPlan === 'string' && editingPlan === '_warmup_'}
                />
            )}
            {view === 'log' && (
                <WorkoutLog onBack={handleBack} />
            )}
          </div>
        </div>
    </>
  );
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { useLogger } from '../contexts/LoggingContext';

const CRASH_FLAG_KEY = 'app_crash_detected';

interface Props {
  children: ReactNode;
  logError: (error: Error, componentStack: string) => void;
}

interface State {
  hasError: boolean;
}

// Fixed ErrorBoundaryInternal by explicitly using React.Component and ensuring types are inherited correctly.
class ErrorBoundaryInternal extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  public static getDerivedStateFromError(_: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
    this.props.logError(error, errorInfo.componentStack);
    // Set a flag in localStorage so we can detect this crash on the next app load.
    try {
        localStorage.setItem(CRASH_FLAG_KEY, 'true');
    } catch (e) {
        console.error("Could not set crash flag in localStorage:", e);
    }
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen w-screen bg-red-900 text-white flex flex-col items-center justify-center p-4 text-center">
            <h1 className="text-4xl font-bold">התרחשה שגיאה</h1>
            <p className="mt-4 text-lg">אפליקציית השעון נתקלה בבעיה בלתי צפויה.</p>
            <p className="mt-2 text-md text-red-200">
                נסה לרענן את הדף. אם הבעיה נמשכת, אנא פתח את תפריט ההגדרות, עבור לקטע 'מפתחים' והעתק את פרטי ניפוי השגיאות כדי לדווח על הבעיה.
            </p>
            <button
                onClick={() => window.location.reload()}
                className="mt-8 px-6 py-3 bg-red-600 rounded-lg font-semibold hover:bg-red-700 transition-colors"
            >
                רענן דף
            </button>
        </div>
      );
    }

    return this.props.children;
  }
}

// Wrapper component to inject the logger context function into the class component
export const ErrorBoundary: React.FC<{children: ReactNode}> = ({ children }) => {
    const { logError } = useLogger();
    // Explicitly pass children as a prop to satisfy TypeScript validation
    return <ErrorBoundaryInternal logError={logError}>{children}</ErrorBoundaryInternal>;
};

import { GoogleGenAI, Type, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { kv } from "@vercel/kv";

const geminiApiKey = process.env.API_KEY;
const youtubeApiKey = process.env.YOUTUBE_API_KEY;

const safetySettings = [
  {
    category: HarmCategory.HARM_CATEGORY_HARASSMENT,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
  {
    category: HarmCategory.HARM_CATEGORY_HATE_SPEECH,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
  {
    category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
  {
    category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
];


const handleExerciseInfoRequest = async (exerciseName: string, force_refresh: boolean) => {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey! });
    const normalizedExerciseName = exerciseName.trim().toLowerCase();
    const exerciseCacheKey = `exercise:${normalizedExerciseName}`;

    // STAGE 0: Check our persistent KV cache first.
    if (!force_refresh) {
        try {
            const cachedData = await kv.get(exerciseCacheKey);
            if (cachedData) {
                return { status: 200, body: cachedData };
            }
        } catch (kvError) {
            console.error("Vercel KV 'get' operation failed. This is likely a configuration issue. The app will proceed without server-side caching for this request.", kvError);
        }
    }

    // STAGE 1: Fetch YouTube videos and Gemini text in parallel for efficiency.

    // Task 1: Search YouTube for relevant videos.
    const searchYouTube = async () => {
        // A more direct and effective search query.
        const searchQuery = `how to do ${exerciseName} proper form tutorial short`;
        const youtubeApiUrl = `https://www.googleapis.com/youtube/v3/search?part=snippet&q=${encodeURIComponent(searchQuery)}&type=video&videoDuration=short&maxResults=5&key=${youtubeApiKey}`;

        try {
            const youtubeResponse = await fetch(youtubeApiUrl);
            if (!youtubeResponse.ok) {
                const errorData = await youtubeResponse.json();
                console.error("YouTube API Error:", errorData);
                return []; // Return empty array on error, don't fail the whole request.
            }
            const youtubeData = await youtubeResponse.json();
            return youtubeData.items.map((item: any) => item.id.videoId).filter(Boolean);
        } catch (error) {
            console.error("Failed to fetch from YouTube API:", error);
            return [];
        }
    };

    // Task 2: Ask Gemini for instructional text.
    const getGeminiText = async () => {
        const textGenerationPrompt = `
          You are an expert fitness coach. For the exercise "${exerciseName}", generate the following information IN THE SAME LANGUAGE as the original exercise name ("${exerciseName}"):
          - "instructions": A clear, step-by-step guide. Each step MUST be on a new line, separated by '\\n'.
          - "tips": 2-4 concise tips for proper form.
          - "generalInfo": A short paragraph about the exercise, its benefits, and primary muscles targeted.
          - "language": The ISO 639-1 code for the language you are writing in.

          Return ONLY a single, valid JSON object with the specified structure. Do not include video information.
        `;

        const textResponse = await ai.models.generateContent({
            // Using gemini-3-flash-preview for basic text tasks like fetching exercise info.
            model: 'gemini-3-flash-preview',
            contents: textGenerationPrompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        instructions: { type: Type.STRING },
                        tips: { type: Type.ARRAY, items: { type: Type.STRING } },
                        generalInfo: { type: Type.STRING },
                        language: { type: Type.STRING },
                    },
                    required: ["instructions", "tips", "generalInfo", "language"],
                },
                safetySettings: safetySettings,
            },
        });
        const cleanedJsonString = textResponse.text.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();
        if (!cleanedJsonString) {
            throw new Error("Received an empty text response from the AI service.");
        }
        return JSON.parse(cleanedJsonString);
    };

    // Execute both tasks concurrently.
    const [videoIds, textData] = await Promise.all([
        searchYouTube(),
        getGeminiText()
    ]);

    // STAGE 2: Combine the results.
    const finalData = {
        ...textData,
        primaryVideoId: videoIds.length > 0 ? videoIds[0] : null,
        alternativeVideoIds: videoIds.length > 1 ? videoIds.slice(1, 4) : [],
    };

    // If we failed to get any videos, update the text to inform the user.
    if (!finalData.primaryVideoId) {
        finalData.instructions = "לא נמצאו סרטוני הדרכה מתאימים עבור תרגיל זה. המידע הכתוב עדיין זמין.";
    }

    // Attempt to save to KV but don't let it block the response.
    try {
        await kv.set(exerciseCacheKey, finalData);
    } catch (kvError) {
        console.error("Vercel KV 'set' operation failed. The response was sent to the user, but it was not cached on the server.", kvError);
    }

    return { status: 200, body: finalData };
}

const baseSystemInstruction = `You are a world-class expert in human performance and rehabilitation, with deep knowledge in sports science, physiotherapy, and occupational therapy. Your primary goal is to help users create safe, effective, and personalized plans.

**Interaction Flow:**
1.  **Be Conversational:** Act like a personal coach or therapist. If the user's request is vague (e.g., "give me a plan"), you MUST ask clarifying questions before creating a plan. Ask about their goals, available time, physical condition, available equipment, etc.
2.  **Generate the Plan:** Once you have enough information, generate the plan. It could be a workout plan, a physiotherapy routine, a set of daily activities for occupational therapy, etc.
3.  **Provide a Summary:** FIRST, provide a friendly, human-readable summary of the plan you've created. This summary should appear as regular text.
4.  **Provide the JSON:** AFTER the summary, you MUST provide the plan as a single, valid JSON object enclosed in a markdown code block (\`\`\`json ... \`\`\`). Do NOT include any other text after the JSON block.

**User Profile:**
- The user's profile information may be provided below.
- This information is persistent for the entire conversation. If it exists, you MUST use it to tailor the plan and you MUST NOT ask for information that is already provided in the profile (e.g., don't ask for equipment if it's already listed).

**JSON Rules:**
- The JSON MUST conform to the TypeScript interface provided below.
- The \`type\` for steps can be 'exercise' for physical movements or 'rest' for breaks. Use these categories broadly. For example, a physiotherapy stretch is an 'exercise'.
- **CRITICAL:** The \`name\` property for each step MUST ONLY contain the base name of the activity (e.g., "Push-ups", "Push-ups", "Gentle Wrist Stretches"). DO NOT include set counts, reps, or durations in the activity name itself.

**Language:**
- You MUST respond in the same language as the user's last message. This includes all conversational text, the plan summary, and all strings within the JSON object (like \`name\` fields for the plan and its steps).

**Workout Plan Interface:**
\`\`\`typescript
interface WorkoutStep {
  id: string; // Should be a unique placeholder like "step_1"
  name: string; // e.g., "Push-ups", "Rest"
  type: 'exercise' | 'rest';
  isRepBased: boolean; // true for reps, false for time-based
  duration: number; // Duration in seconds (if not rep-based)
  reps: number; // Number of reps (if rep-based)
}

interface WorkoutPlan {
  name: string; // A descriptive name for the plan, e.g., "Full Body Beginner Workout"
  steps: WorkoutStep[];
  executionMode?: 'linear' | 'circuit';
}
\`\`\`
`;

const handleChatRequest = async (history: any[], message: string, profileContext?: string) => {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey! });

    let finalSystemInstruction = baseSystemInstruction;
    if (profileContext) {
        finalSystemInstruction += `\n\n--- IMPORTANT USER PROFILE ---\n${profileContext}\n--- END USER PROFILE ---`;
    }

    const chat = ai.chats.create({
        // Using gemini-3-pro-preview for complex reasoning task (workout plan generation).
        model: 'gemini-3-pro-preview',
        history,
        config: {
            safetySettings: safetySettings,
            systemInstruction: finalSystemInstruction,
        },
    });

    const response = await chat.sendMessage({ message });
    return { status: 200, body: { responseText: response.text } };
};


export default async function handler(req: any, res: any) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    return res.status(405).end(`Method ${req.method} Not Allowed`);
  }

  if (!geminiApiKey) {
    console.error(`API_KEY (for Gemini) is not configured on the server.`);
    return res.status(500).json({ 
        message: `The Gemini API key (API_KEY) is not configured. Please set it in your project's environment variables.`,
        code: "API_KEY_MISSING"
    });
  }

  const { exerciseName, force_refresh, chatRequest, checkCache } = req.body;

  try {
      let result;
      if (chatRequest) {
          // Handle AI Planner Chat Request
          const { history, message, profileContext } = chatRequest;
          if (!message || typeof message !== 'string') {
              return res.status(400).json({ message: 'A valid message is required for chat requests.' });
          }
          result = await handleChatRequest(history || [], message, profileContext);
      } else if (checkCache && Array.isArray(checkCache)) {
          // Handle server-side cache check
          const keys = checkCache.map(name => `exercise:${name.trim().toLowerCase()}`);
          if (keys.length === 0) {
              return res.status(200).json({ uncachedNames: [] });
          }
          try {
              const results = await kv.mget(...keys);
              const uncachedNames = checkCache.filter((_, index) => results[index] === null);
              return res.status(200).json({ uncachedNames });
          } catch (kvError) {
               console.error("Vercel KV 'mget' operation failed.", kvError);
               // If KV fails, assume nothing is cached so the client tries to fetch everything.
               return res.status(200).json({ uncachedNames: checkCache });
          }
      } else if (exerciseName) {
          // Handle Exercise Info Request
          if (typeof exerciseName !== 'string') {
              return res.status(400).json({ message: 'A valid exerciseName string is required.' });
          }
          if (!youtubeApiKey) {
              console.error("YOUTUBE_API_KEY is not configured on the server.");
              return res.status(200).json({
                  primaryVideoId: null,
                  alternativeVideoIds: [],
                  instructions: "מפתח YouTube API אינו מוגדר בשרת.",
                  tips: [ "נדרש מפתח YouTube API כדי לחפש ולהציג סרטונים. המפתח חסר כרגע בהגדרות השרת." ],
                  generalInfo: "",
                  language: 'he',
              });
          }
          result = await handleExerciseInfoRequest(exerciseName, force_refresh);
      } else {
        return res.status(400).json({ message: 'Invalid request. Must include exerciseName, chatRequest, or checkCache.' });
      }

      return res.status(result.status).json(result.body);

  } catch (error: any) {
    console.error("Error in API handler:", error);

    let errorPayload: any;
    let statusCode: number = 500;

    // Try to parse the error message if it's a JSON string from the API
    try {
        // The error message might be prefixed with text, so find the start of the JSON object.
        const jsonStartIndex = error.message.indexOf('{');
        if (jsonStartIndex > -1) {
            const potentialJson = error.message.substring(jsonStartIndex);
            const parsed = JSON.parse(potentialJson);
            errorPayload = parsed.error || parsed; // Handle cases where it's wrapped in an 'error' object
        }
    } catch (e) {
        // Parsing failed, will use fallback.
    }

    // If we couldn't parse a structured error, create a fallback payload from the error object itself.
    if (!errorPayload) {
        errorPayload = {
            message: error.message || 'An unknown error occurred.',
            status: error.status || 'UNKNOWN',
            code: error.code || 500
        };
    }

    statusCode = errorPayload.code || statusCode;


    // Check for Quota Exceeded error
    if (statusCode === 429 || errorPayload.status === 'RESOURCE_EXHAUSTED') {
        const userFriendlyMessage = "מכסת השימוש היומית ב-API נוצלה. שירותי הבינה המלאכותית יחזרו לפעול מחר.";
        const technicalDetails = `פרטים טכניים: ${errorPayload.message}`;

        const clientError = chatRequest 
            ? { responseText: `שגיאה: ${userFriendlyMessage}` }
            : {
                primaryVideoId: null,
                alternativeVideoIds: [],
                instructions: userFriendlyMessage,
                tips: [
                    "זוהי מגבלה זמנית של הגרסה החינמית.", 
                    "ניתן להמשיך להשתמש בשאר תכונות האפליקציה."
                ],
                generalInfo: technicalDetails, // Put technical details here for the user to see.
                language: 'he',
              };

        return res.status(429).json(clientError);
    }

    // Handle other generic errors
    const genericErrorMessage = `אירעה שגיאה: ${errorPayload.message}`;
    const clientError = chatRequest 
        ? { responseText: `שגיאה: ${genericErrorMessage}` }
        : {
            primaryVideoId: null,
            alternativeVideoIds: [],
            instructions: genericErrorMessage,
            tips: ["אנא נסה שוב מאוחר יותר.", "אם הבעיה נמשכת, בדוק את קונסולת המפתחים."],
            generalInfo: "לא ניתן היה לאחזר מידע עבור תרגיל זה.",
            language: 'he',
          };

    return res.status(statusCode < 400 ? 500 : statusCode).json(clientError);
  }
}

export interface WorkoutStep {
  id: string;
  name: string; // Now the base name, e.g., "Push-ups"
  type: 'exercise' | 'rest';
  isRepBased: boolean;
  duration: number;
  reps: number;
  isWarmup?: boolean;
  enabled?: boolean;
  instructions?: string; // Short "how-to" instructions generated by AI
  // New structured data for sets, replacing "(Set X/Y)" in the name
  set?: {
    current: number;
    total: number;
  };
}

export interface WorkoutPlan {
  id: string;
  name: string;
  steps: WorkoutStep[];
  executionMode?: 'linear' | 'circuit';
  color?: string;
  isLocked?: boolean;
  isSmartPlan?: boolean;
  order?: number;
  // Internal schema version to help with migrations
  version?: number;
}

export enum StepStatus {
  Completed = 'completed',
  Skipped = 'skipped',
}

export interface PerformedStep {
  step: WorkoutStep;
  status: StepStatus;
  durationMs: number;
}


export interface WorkoutLogEntry {
    id: string;
    date: string; // ISO string
    planName: string;
    durationSeconds: number;
    steps: WorkoutStep[]; // The originally planned steps
    planIds?: string[];
    performedSteps: PerformedStep[]; // The new, detailed log of what actually happened
}

