        try {
            const cachedData = await kv.get(exerciseCacheKey);
            if (cachedData) {
                return { status: 200, body: cachedData };
            }
        } catch (kvError) {
            console.error("Vercel KV 'get' operation failed.", kvError);
        }
    }

    // STAGE 1: Fetch YouTube videos and Gemini text in parallel
    const searchYouTube = async () => {
        const searchQuery = `how to do ${exerciseName} proper form tutorial short`;
        const youtubeApiUrl = `https://www.googleapis.com/youtube/v3/search?part=snippet&q=${encodeURIComponent(searchQuery)}&type=video&videoDuration=short&maxResults=5&key=${youtubeApiKey}`;

        try {
            const youtubeResponse = await fetch(youtubeApiUrl);
            if (!youtubeResponse.ok) return [];
            const youtubeData = await youtubeResponse.json();
            return youtubeData.items.map((item: any) => item.id.videoId).filter(Boolean);
        } catch (error) {
            return [];
        }
    };

    const getGeminiText = async () => {
        const textGenerationPrompt = `
          You are an expert fitness coach. For the exercise "${exerciseName}", generate instructions IN THE SAME LANGUAGE as the name:
          - "instructions": Clear step-by-step guide.
          - "tips": 2-4 concise tips.
          - "generalInfo": Paragraph about targeted muscles.
          - "language": ISO code.
        `;

        const textResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: textGenerationPrompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        instructions: { type: Type.STRING },
                        tips: { type: Type.ARRAY, items: { type: Type.STRING } },
                        generalInfo: { type: Type.STRING },
                        language: { type: Type.STRING },
                    },
                    required: ["instructions", "tips", "generalInfo", "language"],
                },
                safetySettings: safetySettings,
            },
        });
        return JSON.parse(textResponse.text);
    };

    const [videoIds, textData] = await Promise.all([searchYouTube(), getGeminiText()]);
    const finalData = { ...textData, primaryVideoId: videoIds[0] || null, alternativeVideoIds: videoIds.slice(1, 4) };
    try { await kv.set(exerciseCacheKey, finalData); } catch (e) {}
    return { status: 200, body: finalData };
}

const baseSystemInstruction = `You are a world-class expert in human performance and rehabilitation. Help users create personalized workout/therapy plans.

**Interaction Flow:**
1. Be Conversational.
2. Generate the Plan.
3. Provide a Summary.
4. Provide the JSON in a markdown block.

**JSON Rules:**
- Conform to the WorkoutPlan interface.
- **CRITICAL:** Include an "instructions" field for EVERY step (especially exercises). 
- The "instructions" should be a 1-2 sentence description of how to perform the movement correctly.
- Respond in the user's language.

**Workout Plan Interface:**
\`\`\`typescript
interface WorkoutStep {
  id: string;
  name: string;
  type: 'exercise' | 'rest';
  isRepBased: boolean;
  duration: number;
  reps: number;
  instructions: string; // Brief execution guide
}

interface WorkoutPlan {
  name: string;
  steps: WorkoutStep[];
  executionMode?: 'linear' | 'circuit';
}
\`\`\`
`;

const handleChatRequest = async (history: any[], message: string, profileContext?: string) => {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey! });
    let finalSystemInstruction = baseSystemInstruction;
    if (profileContext) finalSystemInstruction += `\n\n--- USER PROFILE ---\n${profileContext}`;

    const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        history,
        config: { safetySettings, systemInstruction: finalSystemInstruction },
    });

    const response = await chat.sendMessage({ message });
    return { status: 200, body: { responseText: response.text } };
};


export default async function handler(req: any, res: any) {
  if (req.method !== 'POST') return res.status(405).end();
  if (!geminiApiKey) return res.status(500).json({ message: "API_KEY missing", code: "API_KEY_MISSING" });

  const { exerciseName, force_refresh, chatRequest, checkCache } = req.body;
  try {
      let result;
      if (chatRequest) result = await handleChatRequest(chatRequest.history, chatRequest.message, chatRequest.profileContext);
      else if (checkCache) {
          const keys = checkCache.map((n: string) => `exercise:${n.trim().toLowerCase()}`);
          const results = await kv.mget(...keys);
          return res.status(200).json({ uncachedNames: checkCache.filter((_: any, i: number) => results[i] === null) });
      } else if (exerciseName) result = await handleExerciseInfoRequest(exerciseName, force_refresh);
      else return res.status(400).end();

      return res.status(result.status).json(result.body);
  } catch (error: any) {
    return res.status(500).json({ message: error.message });
  }
}

