const CustomSoundUploader: React.FC<{
  label: string;
  sound?: CustomSound;
  onUpload: (sound: CustomSound) => void;
  onReset: () => void;
}> = ({ label, sound, onUpload, onReset }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) { alert("File too large"); return; }
    const reader = new FileReader();
    reader.onload = (e) => onUpload({ name: file.name, dataUrl: e.target?.result as string });
    reader.readAsDataURL(file);
  };
  return (
    <div className="flex items-center justify-between">
      <span className="text-white">{label}</span>
      <div className="flex items-center gap-2">
        <span className="text-sm text-gray-400 truncate max-w-[100px]">{sound?.name ?? 'Default'}</span>
        <input type="file" accept="audio/*" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
