    handleDiscardGuestData,
    logManualSession,
  } = workoutContext;

  const stopwatch = useStopwatch();
  const wasWorkoutActive = useRef(false);
  const lastActiveWorkoutRef = useRef<ActiveWorkout | null>(null);
  const [workoutCompleted, setWorkoutCompleted] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isWorkoutOpen, setIsWorkoutOpen] = useState(false);
  const [preWorkoutTimeLeft, setPreWorkoutTimeLeft] = useState<number | null>(null);
  const { logAction, getDebugReportAsString } = useLogger();
  const [showCrashNotification, setShowCrashNotification] = useState(false);
  const [manualSessionLog, setManualSessionLog] = useState<PerformedStep[]>([]);
  const [isLoggingModalOpen, setIsLoggingModalOpen] = useState(false);
  const prevCycleCount = useRef(0);

  useEffect(() => {
    try {
        if (localStorage.getItem(CRASH_FLAG_KEY) === 'true') setShowCrashNotification(true);
    } catch (e) {}
  }, []);

  const handleCopyCrashReport = useCallback(() => {
    const report = getDebugReportAsString({ settings, user, workoutContext });
    navigator.clipboard.writeText(report).finally(() => {
        setShowCrashNotification(false);
        localStorage.removeItem(CRASH_FLAG_KEY);
    });
  }, [getDebugReportAsString, settings, user, workoutContext]);

  const handleDismissCrashReport = useCallback(() => {
    setShowCrashNotification(false);
    localStorage.removeItem(CRASH_FLAG_KEY);
  }, []);

  useEffect(() => {
    const handleFirstInteraction = () => {
      resumeAudioContext();
      window.removeEventListener('click', handleFirstInteraction);
    };
    window.addEventListener('click', handleFirstInteraction);
    return () => window.removeEventListener('click', handleFirstInteraction);
  }, []);

  const nextStepWithTime = useCallback((status: StepStatus) => {
      workoutContext.nextStep(Date.now(), status);
  }, [workoutContext]);

  const isWorkoutActive = !!(activeWorkout && currentStep);
  const isRepStep = isWorkoutActive && currentStep.isRepBased;
  const countdownDuration = isWorkoutActive && !isRepStep ? currentStep.duration : (isWorkoutActive && isRepStep ? 0 : settings.countdownDuration);
  const isRestStep = isWorkoutActive && currentStep.type === 'rest';

  const countdown = useCountdown(
    countdownDuration, 
    settings.countdownRestDuration, 
    settings,
    (isWorkoutActive && !isRepStep) ? () => nextStepWithTime(StepStatus.Completed) : undefined,
    isWorkoutActive ? `${currentStep.id}-${activeWorkout.currentStepIndex}-${activeWorkout.stepRestartKey || 0}` : undefined,
    isRestStep
  );

  useEffect(() => {
    if (!isWorkoutActive && countdown.cycleCount > prevCycleCount.current) {
        const cyclesCompleted = countdown.cycleCount - prevCycleCount.current;
        const newPerformedSteps: PerformedStep[] = [];
        for(let i=0; i < cyclesCompleted; i++) {
            newPerformedSteps.push({ step: { id: `m-${i}`, name: 'Interval', type: 'exercise', isRepBased: false, duration: settings.countdownDuration, reps: 0 }, status: StepStatus.Completed, durationMs: settings.countdownDuration * 1000 });
        }
        setManualSessionLog(currentLog => [...currentLog, ...newPerformedSteps]);
    }
    prevCycleCount.current = countdown.cycleCount;
  }, [countdown.cycleCount, isWorkoutActive, settings.countdownDuration]);

  const isPastHalfway = settings.showCountdown && countdown.isRunning && countdown.timeLeft <= countdownDuration / 2 && countdown.timeLeft > 0;

  useEffect(() => {
    if (activeWorkout) lastActiveWorkoutRef.current = activeWorkout;
  }, [activeWorkout]);

  useEffect(() => {
    document.body.style.backgroundColor = settings.backgroundColor;
  }, [settings.backgroundColor]);

  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | undefined;
    if (isPreparingWorkout) {
        let countdownVal = settings.preWorkoutCountdownDuration;
        setPreWorkoutTimeLeft(countdownVal);
        timer = setInterval(() => {
            countdownVal -= 1;
            setPreWorkoutTimeLeft(countdownVal);
            if (countdownVal <= 0) {
                clearInterval(timer);
                setTimeout(() => commitStartWorkout(), 1000);
            }
        }, 1000);
        return () => { if (timer) clearInterval(timer); };
    } else {
        setPreWorkoutTimeLeft(null);
    }
  }, [isPreparingWorkout, commitStartWorkout, settings.preWorkoutCountdownDuration]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) document.documentElement.requestFullscreen();
    else if (document.exitFullscreen) document.exitFullscreen();
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return;
      const key = event.key.toLowerCase();
      if (key === ' ') {
          event.preventDefault();
          if (isWorkoutActive) isWorkoutPaused ? resumeWorkout() : pauseWorkout();
          else {
              if (workoutCompleted) setWorkoutCompleted(false);
              stopwatch.isRunning ? stopwatch.stop() : stopwatch.start();
              countdown.isRunning ? countdown.stop() : countdown.start();
          }
      }
      if (key === 'escape') {
          setIsSettingsOpen(false);
          setIsWorkoutOpen(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [stopwatch, countdown, isWorkoutActive, isWorkoutPaused, workoutCompleted]);

  useEffect(() => {
    if (isWorkoutActive) {
      if (!wasWorkoutActive.current) {
        setWorkoutCompleted(false);
        stopwatch.stop();
        countdown.stop();
        stopwatch.reset();
      }
      isWorkoutPaused ? stopwatch.stop() : stopwatch.start();
      (isWorkoutPaused || isCountdownPaused) ? countdown.stop() : countdown.start();
      wasWorkoutActive.current = true;
    } else {
      if (wasWorkoutActive.current && lastActiveWorkoutRef.current) {
          contextStopWorkout({ completed: true, durationMs: stopwatch.time, finishedWorkout: lastActiveWorkoutRef.current });
          setWorkoutCompleted(true);
          lastActiveWorkoutRef.current = null;
      }
      wasWorkoutActive.current = false;
    }
  }, [isWorkoutActive, isWorkoutPaused, isCountdownPaused]);

  if (preWorkoutTimeLeft !== null) return <PreWorkoutCountdown timeLeft={preWorkoutTimeLeft} onDoubleClick={toggleFullScreen} />;
  if (settings.stealthModeEnabled) return <div className="fixed inset-0 bg-black z-[200] animate-fadeIn"></div>;

  const dynamicStyles = {
    '--countdown-font-size': `clamp(2.5rem, ${22 * (settings.countdownSize / 100)}vmin, 20rem)`,
    '--stopwatch-font-size': `clamp(1.5rem, 8vw, ${2 + (settings.stopwatchSize / 100) * 1.5}rem)`,
    '--countdown-controls-scale': settings.countdownControlsSize / 100,
    '--stopwatch-controls-scale': settings.stopwatchControlsSize / 100,
  } as React.CSSProperties;

  const isResting = (isWorkoutActive && currentStep.type === 'rest') || (!isWorkoutActive && countdown.isResting && settings.showRestTitleOnDefaultCountdown);
  let bgColor = isResting ? settings.restBackgroundColor : (isPastHalfway ? settings.halfwayColor : settings.backgroundColor);
  if (workoutCompleted) bgColor = '#6ee7b7';

  return (
    <div 
        onDoubleClick={(e) => { if (e.target === e.currentTarget) toggleFullScreen(); }} 
        className={`h-screen overflow-hidden flex flex-col p-4 select-none theme-transition`} 
        style={{ ...dynamicStyles, backgroundColor: bgColor, color: bgColor === 'black' || bgColor === '#000000' ? 'white' : 'inherit' }}
    >
      {showCrashNotification && <CrashNotification onCopy={handleCopyCrashReport} onDismiss={handleDismissCrashReport} />}
      {showGuestMergeModal && <GuestDataMergeModal guestPlans={guestPlansToMerge} guestHistoryCount={guestHistoryToMerge.length} onMerge={handleMergeGuestData} onDiscard={handleDiscardGuestData} />}
      {importNotification && <ImportNotification message={importNotification.message} planName={importNotification.planName} onClose={clearImportNotification} type={importNotification.type} />}
      {isLoggingModalOpen && <LogSessionModal onSave={(name) => { logManualSession(name, stopwatch.time, manualSessionLog); stopwatch.reset(); countdown.resetCycleCount(); setManualSessionLog([]); setIsLoggingModalOpen(false); }} onClose={() => setIsLoggingModalOpen(false)} />}

      <SettingsMenu isOpen={isSettingsOpen} setIsOpen={setIsSettingsOpen} />
      <WorkoutMenu isOpen={isWorkoutOpen} setIsOpen={setIsWorkoutOpen} />

      {/* Live Info Panel */}
      {isWorkoutActive && settings.showLiveInfoPanel && <LiveInfoPanel instructions={currentStep.instructions} />}

      <main onDoubleClick={toggleFullScreen} className="flex-grow flex flex-col items-center justify-center w-full max-w-4xl mx-auto min-h-0">
        <div className="text-center mb-2 min-h-[3.5rem] flex items-end justify-center">
            {workoutCompleted ? <p className="text-8xl font-bold" dir="rtl">סוף האימון</p> :
             (isWorkoutActive && currentStep?.type === 'rest' ? <p className="text-8xl font-bold" dir="rtl">מנוחה</p> :
              (isWorkoutActive && currentStep?.isWarmup ? <p className="text-8xl font-bold" dir="rtl">חימום</p> : null))}
        </div>

        {settings.showCountdown && (
          isRepStep ? <RepDisplay reps={currentStep.reps} onComplete={() => nextStepWithTime(StepStatus.Completed)} /> :
          <>
            <CountdownDisplay timeLeft={countdown.timeLeft} />
            {settings.showCountdownControls && <CountdownControls isRunning={isWorkoutActive ? (!isWorkoutPaused && !isCountdownPaused) : (countdown.isRunning || countdown.isResting)} start={isWorkoutActive ? resumeStepCountdown : countdown.start} stop={isWorkoutActive ? pauseStepCountdown : countdown.stop} reset={isWorkoutActive ? restartCurrentStep : countdown.reset} />}
          </>
        )}

        <div className="text-center mt-4 min-h-[2.5rem] flex items-start justify-center">
          {isWorkoutActive && currentStep.type === 'exercise' && <p className="text-2xl">{isWorkoutPaused ? 'PAUSED' : getStepDisplayName(currentStep)}</p>}
        </div>
      </main>

      {(settings.showTimer || settings.showCycleCounter) && (
        <footer className="w-full max-w-3xl mx-auto flex flex-col items-center gap-1">
            <div className="text-center mb-2 min-h-[1.75rem] flex items-center justify-center">
              {isWorkoutActive && settings.showNextExercise && nextUpcomingStep && <p className="text-xl text-gray-400">Next Up: <span className="font-bold text-gray-300">{getStepDisplayName(nextUpcomingStep)}</span></p>}
            </div>
            {settings.showTimer && <TimerDisplay time={stopwatch.time} />}
            <Controls isRunning={stopwatch.isRunning} start={() => { if(workoutCompleted) setWorkoutCompleted(false); stopwatch.start(); }} stop={stopwatch.stop} reset={() => { stopwatch.reset(); countdown.resetCycleCount(); setManualSessionLog([]); }} cycleCount={settings.showCycleCounter && !isWorkoutActive ? countdown.cycleCount : null} resetCycleCount={countdown.resetCycleCount} showTimer={settings.showTimer} showStopwatchControls={settings.showStopwatchControls} isWorkoutActive={isWorkoutActive} nextStep={() => nextStepWithTime(StepStatus.Skipped)} previousStep={() => workoutContext.previousStep(Date.now())} workoutStepInfo={isWorkoutActive ? { current: activeWorkout.currentStepIndex + 1, total: activeWorkout.plan.steps.length } : undefined} showLogSessionButton={settings.showLogSessionButton && !isWorkoutActive && manualSessionLog.length > 0} onLogSession={() => setIsLoggingModalOpen(true)} />
        </footer>
      )}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <LoggingProvider>
        <SettingsProvider>
          <WorkoutProvider>
            <ErrorBoundary>
              <AppContent />
            </ErrorBoundary>
          </WorkoutProvider>
        </SettingsProvider>
      </LoggingProvider>
    </AuthProvider>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo, useLayoutEffect } from 'react';
import { useWorkout } from '../contexts/WorkoutContext';
