  const [activeVideoId, setActiveVideoId] = useState<string | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchInfo = async () => {
      if (!exerciseName) return;

      // If we have an instructions override and it's visible, skip loading from API if we only want the text
      if (instructionsOverride && !info) {
          setInfo({
              primaryVideoId: '',
              alternativeVideoIds: [],
              instructions: instructionsOverride,
              tips: [],
              generalInfo: 'AI Generated Instructions',
              language: 'auto'
          });
          setIsLoading(false);
          return;
      }

      setIsLoading(true);
      setError(null);
      try {
        const result = await getExerciseInfo(exerciseName);
        setInfo(result);
        setActiveVideoId(result.primaryVideoId);
      } catch (e) {
        setError(e instanceof Error ? e.message : "Error");
      } finally {
        setIsLoading(false);
      }
    };
    if (isVisible && exerciseName) fetchInfo();
  }, [exerciseName, isVisible, instructionsOverride]);

  useEffect(() => {
    if (isVisible && activeVideoId) setVideoUrl(`https://www.youtube.com/embed/${activeVideoId}?autoplay=1`);
    else setVideoUrl(null);
