      {isOpen && <div className="fixed inset-0 bg-black/60 z-40" onClick={() => setIsOpen(false)}></div>}

      <ExerciseInfoModal exerciseName={exerciseToInspect} instructionsOverride={inspectInstructions} onClose={() => setIsModalVisible(false)} isVisible={isModalVisible} />

      <div className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/80 backdrop-blur-md shadow-2xl z-50 transform transition-all ease-in-out ${isOpen ? 'translate-x-0 opacity-100' : '-translate-x-full opacity-0 pointer-events-none'}`}>
          <div className="p-6 overflow-y-auto h-full">
            {/* ... PlanList logic calling handleInspectExercise ... */}
            <PlanList onInspectExercise={handleInspectExercise} onSelectPlan={()=>{}} onCreateNew={()=>{}} onInitiateDelete={()=>{}} onShowLog={()=>{}} onShowInfo={()=>{}} isPinned={false} onTogglePin={()=>{}} onOpenAiPlanner={()=>{}} />
          </div>
        </div>
