import React, { Component, ReactNode } from 'react';

interface Props {
  logError: (error: Error, componentStack: string) => void;
  children: ReactNode; // Explicitly define children
}

interface State {
  hasError: boolean;
  error: Error | null;
  componentStack: string | null;
}

class ErrorBoundaryInternal extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      componentStack: null,
    };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, componentStack: string) {
    this.props.logError(error, componentStack);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div>
          <h2>Something went wrong.</h2>
          <details style={{ whiteSpace: 'pre-wrap' }}>
            {this.state.error && this.state.error.toString()}
            <br />
            {this.state.componentStack}
          </details>
        </div>
      );
    }

    return this.props.children;
  }
}

const ErrorBoundary = ({ logError, children }: Props) => {
  return <ErrorBoundaryInternal logError={logError} >{children}</ErrorBoundaryInternal>;
};

export default ErrorBoundary;
```


