/**
 * Modal for AI workout generation using Gemini.
 */
const AiPlannerModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
    const [message, setMessage] = useState('');
    const [history, setHistory] = useState<{ role: 'user' | 'model'; parts: { text: string }[] }[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const { importPlan } = useWorkout();
    const { settings } = useSettings();

    const handleSend = async () => {
        if (!message.trim() || isLoading) return;
        const userMsg = message.trim();
        setMessage('');
        setIsLoading(true);

        const newHistory: { role: 'user' | 'model'; parts: { text: string }[] }[] = [...history, { role: 'user', parts: [{ text: userMsg }] }];
        setHistory(newHistory);

        try {
            const profileContext = `User Fitness Level: ${settings.userProfile?.fitnessLevel}. Equipment: ${settings.userProfile?.equipment?.filter(e => e.available).map(e => e.name).join(', ') || 'None'}.`;
            const result = await generateWorkoutPlan(history, userMsg, profileContext);
            setHistory([...newHistory, { role: 'model', parts: [{ text: result }] }]);

            // Detect and import the JSON plan if provided by AI
            const jsonMatch = result.match(/```json\s*([\s\S]*?)\s*```/);
            if (jsonMatch) {
                try {
                    const plan = JSON.parse(jsonMatch[1]);
                    if (plan.name && plan.steps) {
                        importPlan(plan, 'ai');
                    }
                } catch (e) {
                    console.error("AI returned invalid plan JSON", e);
                }
            }
        } catch (error) {
            console.error("AI Planner error:", error);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/70 z-[101] flex items-center justify-center p-4" onClick={onClose}>
            <div className="bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-2xl flex flex-col max-h-[90vh]" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-bold text-white">AI Workout Planner</h3>
                    <button onClick={onClose} className="p-1 rounded-full hover:bg-gray-700">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
                <div className="flex-grow overflow-y-auto mb-4 space-y-4 p-2 bg-gray-900/50 rounded-lg">
                    {history.map((msg, i) => (
                        <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[80%] p-3 rounded-lg ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                                {msg.parts[0].text}
                            </div>
                        </div>
                    ))}
                    {isLoading && <div className="text-gray-400 animate-pulse p-2">Gemini is thinking...</div>}
                </div>
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={message} 
                        onChange={e => setMessage(e.target.value)} 
                        onKeyDown={e => e.key === 'Enter' && handleSend()}
                        className="flex-grow bg-gray-900 text-white p-2 rounded-md focus:outline-none focus:ring-2 ring-blue-500"
                        placeholder="Ask for a custom workout..."
                    />
                    <button onClick={handleSend} disabled={isLoading} className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 disabled:opacity-50">Send</button>
                </div>
            </div>
        </div>
    );
};

/**
 * Editor component for creating or modifying workout plans.
 */
const PlanEditor: React.FC<{
  plan: WorkoutPlan | null;
  onBack: () => void;
  isWarmupEditor?: boolean;
}> = ({ plan, onBack, isWarmupEditor }) => {
    const { savePlan } = useWorkout();
    const { updateSettings, settings } = useSettings();
    const [name, setName] = useState(plan?.name || '');
    const [steps, setSteps] = useState<WorkoutStep[]>(plan?.steps || []);
    const [executionMode, setExecutionMode] = useState<'linear' | 'circuit'>(plan?.executionMode || 'linear');

    const handleSave = () => {
        if (isWarmupEditor) {
            updateSettings({ warmupSteps: steps });
        } else {
            savePlan({
                id: plan?.id || `plan_${Date.now()}`,
                name: name.trim() || 'Untitled Workout',
                steps: steps,
                executionMode: executionMode,
                version: 2
            });
        }
        onBack();
    };

    const addStep = (type: 'exercise' | 'rest') => {
        setSteps([...steps, {
            id: `step_${Date.now()}`,
            name: type === 'exercise' ? 'Exercise' : 'Rest',
            type: type,
            isRepBased: false,
            duration: 30,
            reps: 0
        }]);
    };

    const updateStep = (index: number, updates: Partial<WorkoutStep>) => {
        setSteps(steps.map((s, i) => i === index ? { ...s, ...updates } : s));
    };

    return (
        <div className="flex flex-col h-full space-y-4">
            <div className="flex items-center gap-2">
                <button onClick={onBack} className="p-2 hover:bg-gray-700 rounded-full text-white">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <h2 className="text-2xl font-bold text-white">{isWarmupEditor ? 'Edit Warm-up' : 'Edit Plan'}</h2>
            </div>
            {!isWarmupEditor && (
                <input 
                    type="text" 
                    value={name} 
                    onChange={e => setName(e.target.value)} 
                    placeholder="Workout Name" 
                    className="w-full bg-gray-900 text-white p-2 rounded-md"
                />
            )}
            <div className="flex-grow overflow-y-auto space-y-2 pr-1">
                {steps.map((step, i) => (
                    <div key={i} className="bg-gray-700/50 p-3 rounded-lg flex flex-col gap-2">
                        <input 
                            type="text" 
                            value={step.name} 
                            onChange={e => updateStep(i, { name: e.target.value })} 
                            className="bg-gray-900 text-white p-1 rounded"
                        />
                        <div className="flex items-center gap-4 text-sm text-gray-300">
                             <input type="number" value={step.duration} onChange={e => updateStep(i, { duration: parseInt(e.target.value) })} className="w-16 bg-gray-900 p-1 rounded text-center" />
                             <span>Seconds</span>
                        </div>
                    </div>
                ))}
            </div>
            <div className="flex gap-2 pb-4">
                <button onClick={() => addStep('exercise')} className="flex-1 bg-gray-600 text-white py-2 rounded">+ Exercise</button>
                <button onClick={() => addStep('rest')} className="flex-1 bg-gray-600 text-white py-2 rounded">+ Rest</button>
            </div>
            <button onClick={handleSave} className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold">Save Plan</button>
        </div>
    );
};

