const ExerciseInfoModal: React.FC<{
  exerciseName: string | null;
  providedInstructions?: string;
  onClose: () => void;
  isVisible: boolean;
}> = ({ exerciseName, providedInstructions, onClose, isVisible }) => {
  const [info, setInfo] = useState<ExerciseInfo | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'howto' | 'details'>('howto');
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const modalRef = useRef<HTMLDivElement>(null);
  const [activeVideoId, setActiveVideoId] = useState<string | null>(null);
  const [showLoadingMessage, setShowLoadingMessage] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchInfo = async () => {
      if (!exerciseName) return;
      setIsLoading(true);
      setError(null);
      try {
        const result = await getExerciseInfo(exerciseName);
        setInfo(result);
        setActiveVideoId(result.primaryVideoId);
      } catch (e) {
        setError("Failed to fetch exercise information.");
      } finally {
        setIsLoading(false);
      }
    };
    if (isVisible && exerciseName) fetchInfo();
  }, [exerciseName, isVisible]);

  useEffect(() => {
    if (isVisible && activeVideoId) {
      setVideoUrl(`https://www.youtube.com/embed/${activeVideoId}?autoplay=1`);
    } else {
      setVideoUrl(null);
    }
  }, [isVisible, activeVideoId]);

  const handleMouseDown = (e: React.MouseEvent) => {
    e.preventDefault();
    const startX = e.clientX - position.x;
    const startY = e.clientY - position.y;
    const handleMouseMove = (me: MouseEvent) => setPosition({ x: me.clientX - startX, y: me.clientY - startY });
    const handleMouseUp = () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  const isHebrew = useMemo(() => info?.language === 'he', [info]);
  const parsedInstructions = useMemo(() => {
    if (!info?.instructions) return [];
    return info.instructions.split('\n').map(l => l.trim().replace(/^\d+\.\s*/, '')).filter(Boolean);
  }, [info?.instructions]);

  return (
    <div className={`fixed inset-0 bg-black/70 z-[100] transition-opacity duration-300 ${isVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} onClick={onClose}>
      <div 
        ref={modalRef}
        className="bg-gray-800 rounded-lg shadow-xl w-full max-w-lg flex flex-col max-h-[90vh] absolute top-1/2 left-1/2"
        style={{ transform: `translate(-50%, -50%) translate(${position.x}px, ${position.y}px)` }}
        onClick={e => e.stopPropagation()}
        dir={isHebrew ? 'rtl' : 'ltr'}
      >
        <div className="relative flex justify-center items-center p-4 border-b border-gray-700 cursor-move" onMouseDown={handleMouseDown}>
          <h3 className="text-xl font-bold text-white text-center mx-10">{exerciseName}</h3>
          <button onClick={onClose} className="absolute p-1 rounded-full hover:bg-gray-700 top-3 right-3">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
        <div className="p-4 flex-grow overflow-y-auto">
          {isLoading ? (
            <div className="flex justify-center p-10"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-white"></div></div>
          ) : (
            <>
              {providedInstructions && (
                <div className="mb-4 p-3 bg-blue-900/30 border border-blue-500/30 rounded-lg">
                  <h4 className="text-xs font-bold uppercase text-blue-400 mb-1">{isHebrew ? "הוראות לאימון זה" : "Workout Instructions"}</h4>
                  <p className="text-gray-200 text-sm">{providedInstructions}</p>
                </div>
              )}
              <div className="aspect-video bg-gray-900 rounded-lg overflow-hidden mb-4">
                {videoUrl && <iframe className="w-full h-full" src={videoUrl} allowFullScreen></iframe>}
              </div>
              <h4 className="font-semibold text-white mb-2">{isHebrew ? "הוראות ביצוע" : "Instructions"}</h4>
              <ul className="list-disc list-inside text-gray-300 space-y-1">
                {parsedInstructions.map((line, i) => <li key={i}>{line}</li>)}
              </ul>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

const PlanListItem: React.FC<{
  plan: WorkoutPlan;
  onSelectPlan: (plan: WorkoutPlan) => void;
  onInitiateDelete: (planId: string) => void;
  onInspectExercise: (exerciseName: string, instructions?: string) => void;
