}> = ({ plan, onSelectPlan, onInitiateDelete, onInspectExercise, onShowInfo, onShare, isSelected, onToggleSelection, isDraggable, onDragStart, onDragOver, onDrop, onDragEnd, onDragLeave, isDragTarget, isNewlyImported, index, setRef }) => {
  const { activeWorkout, currentStep, isCountdownPaused, startWorkout, stopWorkout, pauseStepCountdown, resumeStepCountdown, restartCurrentStep, savePlan, workoutHistory } = useWorkout();
  const [isExpanded, setIsExpanded] = useState(false);
  const isActive = activeWorkout?.sourcePlanIds.includes(plan.id) ?? false;

  const displayedSteps = useMemo(() => {
    if (plan.executionMode === 'circuit') return generateCircuitSteps(plan.steps);
    return plan.steps;
  }, [plan.steps, plan.executionMode]);

  return (
    <div 
      ref={setRef}
      className={`rounded-lg transition-all p-1 ${isDraggable ? 'cursor-grab' : ''} ${isDragTarget ? 'border-2 border-dashed border-blue-400' : ''} ${plan.isSmartPlan ? 'bg-purple-900/20' : 'bg-gray-700/50'}`}
      draggable={isDraggable}
      onDragStart={(e) => onDragStart(e, index)}
      onDragOver={(e) => onDragOver(e, index)}
      onDrop={(e) => onDrop(e, index)}
      onDragEnd={onDragEnd}
      onDragLeave={onDragLeave}
      style={{ borderLeft: `4px solid ${plan.color || '#3b82f6'}` }}
    >
      <div className="p-3 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
             {!activeWorkout && <input type="checkbox" checked={isSelected} onChange={() => onToggleSelection(plan.id)} onClick={e => e.stopPropagation()} className="w-4 h-4" />}
             <span className="font-bold text-white truncate max-w-[150px]">{plan.name}</span>
          </div>
          <div className="flex gap-1">
             <button onClick={e => {e.stopPropagation(); onSelectPlan(plan);}} className="p-1 hover:bg-white/10 rounded">✏️</button>
             <button onClick={e => {e.stopPropagation(); onInitiateDelete(plan.id);}} className="p-1 hover:bg-white/10 rounded">🗑️</button>
          </div>
        </div>
        {!activeWorkout && (
            <button 
                onClick={e => {e.stopPropagation(); startWorkout([plan.id]);}}
                className="w-full mt-2 py-1 bg-green-600 rounded text-sm font-bold"
