    <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 animate-fadeIn" onClick={onClose}>
      <div 
        className="bg-gray-800 rounded-lg shadow-xl w-full max-w-lg flex flex-col max-h-[90vh]" 
