// --- Sub-component: AI Planner Chat ---
const AIPlanner: React.FC<{ onPlanGenerated: (plan: WorkoutPlan) => void }> = ({ onPlanGenerated }) => {
  const { settings } = useSettings();
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; parts: { text: string }[] }[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSend = async (text: string = input) => {
    if (!text.trim() || isTyping) return;
    const userMsg = text.trim();
    setInput('');
    const newHistory = [...messages, { role: 'user' as const, parts: [{ text: userMsg }] }];
    setMessages(newHistory);
    setIsTyping(true);

    try {
      const profile = settings.userProfile ? JSON.stringify(settings.userProfile) : '';
      const response = await generateWorkoutPlan(messages, userMsg, profile);

      setMessages([...newHistory, { role: 'model', parts: [{ text: response }] }]);

      // Try to extract JSON
      const jsonMatch = response.match(/```json\s*([\s\S]*?)\s*```/);
      if (jsonMatch) {
        try {
          const plan = JSON.parse(jsonMatch[1]);
          if (plan.name && plan.steps) onPlanGenerated(plan);
        } catch (e) { console.error("Failed to parse plan JSON", e); }
      }
    } catch (e) {
      setMessages([...newHistory, { role: 'model', parts: [{ text: "Sorry, I encountered an error. Please check your connection." }] }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-900/50 rounded-xl border border-white/5 overflow-hidden">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-thin scrollbar-thumb-white/10">
        {messages.length === 0 && (
          <div className="text-center py-10 space-y-4">
            <div className="text-4xl">🤖</div>
            <p className="text-gray-400 text-sm px-6">I'm your AI Coach. Tell me your goals, equipment, and time, and I'll build a custom plan for you.</p>
            <div className="flex flex-wrap justify-center gap-2 px-4">
              {["Full body 20m", "Leg day", "Abs & Cardio"].map(t => (
                <button key={t} onClick={() => handleSend(t)} className="text-xs bg-white/5 hover:bg-white/10 border border-white/10 px-3 py-1.5 rounded-full text-gray-300">
                  {t}
                </button>
              ))}
            </div>
          </div>
        )}
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-gray-800 text-gray-200 rounded-tl-none border border-white/5'}`}>
              {m.parts[0].text.split('```json')[0]}
            </div>
          </div>
        ))}
        {isTyping && <div className="flex justify-start"><div className="bg-gray-800 p-3 rounded-2xl animate-pulse text-gray-500 text-xs">AI is thinking...</div></div>}
      </div>
      <div className="p-3 border-t border-white/5 bg-black/20 flex gap-2">
        <input 
          value={input} 
          onChange={e => setInput(e.target.value)} 
          onKeyDown={e => e.key === 'Enter' && handleSend()}
          placeholder="Type your goal..." 
          className="flex-1 bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-blue-500"
        />
        <button onClick={() => handleSend()} className="bg-blue-600 hover:bg-blue-700 p-2 rounded-lg text-white transition-colors">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
        </button>
      </div>
    </div>
  );
};

// --- Sub-component: Exercise Info Modal ---
const ExerciseInfoModal: React.FC<{ exerciseName: string | null; providedInstructions?: string; onClose: () => void; isVisible: boolean; }> = ({ exerciseName, providedInstructions, onClose, isVisible }) => {
  const [info, setInfo] = useState<ExerciseInfo | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [activeVideoId, setActiveVideoId] = useState<string | null>(null);

  useEffect(() => {
    if (isVisible && exerciseName) {
      setIsLoading(true);
      getExerciseInfo(exerciseName).then(res => {
        setInfo(res);
        setActiveVideoId(res.primaryVideoId);
        setIsLoading(false);
      }).catch(() => setIsLoading(false));
    }
  }, [exerciseName, isVisible]);

  if (!isVisible) return null;
  const isHebrew = info?.language === 'he';

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[110] flex items-center justify-center p-4 animate-fadeIn" onClick={onClose}>
      <div className="bg-gray-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden border border-white/10" onClick={e => e.stopPropagation()} dir={isHebrew ? 'rtl' : 'ltr'}>
        <div className="flex justify-between items-center p-4 border-b border-white/5 bg-gray-900/50">
          <h3 className="text-xl font-bold text-white truncate">{exerciseName}</h3>
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-white transition-colors">✕</button>
        </div>
        <div className="p-5 overflow-y-auto max-h-[80vh] space-y-6">
          {isLoading ? <div className="flex justify-center py-20"><div className="animate-spin h-10 w-10 border-4 border-blue-500 border-t-transparent rounded-full"></div></div> : (
            <>
              {activeVideoId && (
                <div className="aspect-video rounded-xl overflow-hidden shadow-lg ring-1 ring-white/10">
                  <iframe className="w-full h-full" src={`https://www.youtube.com/embed/${activeVideoId}?autoplay=1`} allowFullScreen></iframe>
                </div>
              )}
              {providedInstructions && (
                <div className="bg-blue-500/10 border border-blue-500/20 rounded-xl p-4">
                  <h4 className="text-blue-400 text-xs font-bold uppercase mb-2">Coach's Specific Instruction</h4>
                  <p className="text-gray-200 text-sm leading-relaxed">{providedInstructions}</p>
                </div>
              )}
              <div className="space-y-4">
                <h4 className="text-white font-bold border-l-4 border-blue-500 pl-3">How to Perform</h4>
                <div className="text-gray-300 text-sm space-y-3 whitespace-pre-wrap leading-relaxed">
