                    <div key={i} className="flex gap-3">
                      <span className="text-blue-500 font-mono font-bold">{i + 1}.</span>
                      <span>{line.replace(/^\d+\.\s*/, '')}</span>
                    </div>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

// --- Sub-component: Plan Editor ---
const PlanEditor: React.FC<{ plan: WorkoutPlan; onSave: (p: WorkoutPlan) => void; onCancel: () => void }> = ({ plan, onSave, onCancel }) => {
  const [editedPlan, setEditedPlan] = useState<WorkoutPlan>({ ...plan, steps: [...plan.steps] });

  const addStep = (type: 'exercise' | 'rest') => {
    const newStep: WorkoutStep = {
      id: `step_${Date.now()}`,
      name: type === 'rest' ? 'Rest' : 'New Exercise',
      type,
      isRepBased: false,
      duration: type === 'rest' ? 30 : 40,
      reps: 0
    };
    setEditedPlan({ ...editedPlan, steps: [...editedPlan.steps, newStep] });
  };

  const updateStep = (id: string, updates: Partial<WorkoutStep>) => {
    setEditedPlan({ ...editedPlan, steps: editedPlan.steps.map(s => s.id === id ? { ...s, ...updates } : s) });
  };

  const removeStep = (id: string) => {
    setEditedPlan({ ...editedPlan, steps: editedPlan.steps.filter(s => s.id !== id) });
  };

  return (
    <div className="flex flex-col h-full space-y-4">
      <div className="space-y-3">
        <label className="text-xs font-bold text-gray-500 uppercase tracking-widest">Plan Name</label>
        <input 
          value={editedPlan.name} 
          onChange={e => setEditedPlan({ ...editedPlan, name: e.target.value })}
          className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white font-bold focus:ring-2 ring-blue-500 outline-none"
        />
      </div>

      <div className="flex gap-2">
        <button onClick={() => setEditedPlan({...editedPlan, executionMode: 'linear'})} className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${editedPlan.executionMode !== 'circuit' ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-gray-800 border-white/5 text-gray-400'}`}>LINEAR</button>
        <button onClick={() => setEditedPlan({...editedPlan, executionMode: 'circuit'})} className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${editedPlan.executionMode === 'circuit' ? 'bg-purple-600 border-purple-500 text-white shadow-lg' : 'bg-gray-800 border-white/5 text-gray-400'}`}>CIRCUIT</button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 space-y-3 scrollbar-thin scrollbar-thumb-white/5">
        {editedPlan.steps.map((step, i) => (
          <div key={step.id} className={`p-3 rounded-xl border border-white/5 ${step.type === 'rest' ? 'bg-gray-800/40' : 'bg-gray-700/40 shadow-sm'}`}>
            <div className="flex justify-between items-center mb-2">
              <span className="text-[10px] font-bold text-gray-500 uppercase">Step {i + 1}</span>
              <button onClick={() => removeStep(step.id)} className="text-gray-500 hover:text-red-500 transition-colors">✕</button>
            </div>
            <input 
              value={step.name} 
              onChange={e => updateStep(step.id, { name: e.target.value })}
              className="w-full bg-transparent text-sm font-semibold text-white mb-3 focus:outline-none"
            />
            <div className="flex items-center gap-4">
              <div className="flex-1 flex items-center bg-black/20 rounded-lg p-1">
                <button onClick={() => updateStep(step.id, { isRepBased: false })} className={`flex-1 py-1 rounded text-[10px] font-bold ${!step.isRepBased ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>TIME</button>
                <button onClick={() => updateStep(step.id, { isRepBased: true })} className={`flex-1 py-1 rounded text-[10px] font-bold ${step.isRepBased ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>REPS</button>
              </div>
              <div className="w-20">
                <HoverNumberInput 
                  value={step.isRepBased ? (step.reps || 10) : (step.duration || 30)} 
                  onChange={v => updateStep(step.id, step.isRepBased ? { reps: v } : { duration: v })}
                  className="w-full bg-white/5 border border-white/5 rounded px-2 py-1 text-xs text-center text-white font-mono"
                  min={1}
                />
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-2 gap-3 pt-4 border-t border-white/5">
        <button onClick={() => addStep('exercise')} className="py-2 bg-blue-500/10 hover:bg-blue-500/20 text-blue-400 text-xs font-bold rounded-xl border border-blue-500/20 transition-all">+ EXERCISE</button>
        <button onClick={() => addStep('rest')} className="py-2 bg-gray-500/10 hover:bg-gray-500/20 text-gray-400 text-xs font-bold rounded-xl border border-white/5 transition-all">+ REST</button>
        <button onClick={onCancel} className="col-span-1 py-3 bg-gray-800 text-white text-xs font-bold rounded-xl hover:bg-gray-700">CANCEL</button>
        <button onClick={() => onSave(editedPlan)} className="col-span-1 py-3 bg-green-600 text-white text-xs font-bold rounded-xl hover:bg-green-700 shadow-xl">SAVE PLAN</button>
      </div>
    </div>
  );
};

