const AiPlannerModal: React.FC<{
    onClose: () => void;
}> = ({ onClose }) => {
    type ChatPart = { text: string; isPlanLink?: boolean; planName?: string };
    type ChatMessage = { role: 'user' | 'model'; parts: ChatPart[] };
    const { importPlan } = useWorkout();
    const { settings } = useSettings();
    const AI_CHAT_HISTORY_KEY = 'sportsClockAiChatHistory_v2';
    const [messages, setMessages] = useState<ChatMessage[]>(() => { try { const s = localStorage.getItem(AI_CHAT_HISTORY_KEY); return s ? JSON.parse(s) : []; } catch { return []; } });
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => { localStorage.setItem(AI_CHAT_HISTORY_KEY, JSON.stringify(messages)); messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;
        const userMessage: ChatMessage = { role: 'user', parts: [{ text: input }] };
        const newMessages = [...messages, userMessage];
        setMessages(newMessages);
        setInput('');
        setIsLoading(true);

        let profileContext = '';
        if (settings.userProfile) {
            const { userProfile } = settings;
            const profileParts = [];
            if (userProfile.birthDate) {
                const age = new Date().getFullYear() - new Date(userProfile.birthDate).getFullYear();
                if (age > 0) profileParts.push(`Age: ${age}`);
            }
            if (userProfile.fitnessLevel) profileParts.push(`Fitness Level: ${userProfile.fitnessLevel}`);
            const avail = userProfile.equipment?.filter(e => e.available).map(e => e.name);
            if (avail && avail.length > 0) profileParts.push(`Available Equipment: ${avail.join(', ')}`);
            profileContext = profileParts.join('; ');
        }

        try {
            const responseText = await generateWorkoutPlan(messages, input, profileContext);
            if (responseText.startsWith('Error: ')) { setMessages(prev => [...prev, { role: 'model', parts: [{ text: responseText.substring(7) }] }]); return; }

            const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
            const match = responseText.match(jsonRegex);
            const conversationalText = responseText.replace(jsonRegex, '').trim();
            let finalMessages = [...newMessages];
            if (conversationalText) finalMessages.push({ role: 'model', parts: [{ text: conversationalText }]});
            if (match && match[1]) {
                try {
                    const planJson = JSON.parse(match[1]);
                    // Explicitly set metadata before importing to ensure proper persistence.
                    planJson.isSmartPlan = true;
                    planJson.color = '#a855f7';
                    importPlan(planJson, 'ai');
                    finalMessages.push({ role: 'model', parts: [{ text: '', isPlanLink: true, planName: planJson.name }]});
                } catch (e) { finalMessages.push({ role: 'model', parts: [{ text: "Invalid JSON received." }] }); }
            } else if (!conversationalText) finalMessages.push({ role: 'model', parts: [{ text: responseText }]});
            setMessages(finalMessages);
        } catch (error) { setMessages([...newMessages, { role: 'model', parts: [{ text: "Network error." }] }]); } finally { setIsLoading(false); }
    };

    return (
        <div className="fixed inset-0 bg-gray-900/90 z-[100] flex flex-col p-4" aria-modal="true" role="dialog">
            <AiProfilePanel isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} />
             <div className="flex justify-between items-center mb-4 text-white">
                <button onClick={() => setIsProfileOpen(true)} className="p-2 rounded-full hover:bg-gray-700">👤</button>
                <h2 className="text-xl font-bold">✨ AI Workout Planner</h2>
                <div className="flex items-center gap-2"><button onClick={() => { setMessages([]); localStorage.removeItem(AI_CHAT_HISTORY_KEY); }} className="p-2 rounded-full hover:bg-gray-700">🔄</button><button onClick={onClose} className="p-2 rounded-full hover:bg-gray-700">✕</button></div>
            </div>
            <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
                {messages.map((msg, index) => (
                    <div key={index} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-prose p-3 rounded-lg ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                            {msg.parts.map((part, pi) => part.isPlanLink ? (<div key={pi} dir="auto"><p>הוספתי את תוכנית "{part.planName}" לרשימה שלך.</p><button onClick={onClose} className="mt-2 font-bold text-blue-300 underline">הצג תוכנית</button></div>) : (<p key={pi} className="whitespace-pre-wrap" dir="auto">{part.text}</p>))}
                        </div>
                    </div>
                ))}
                {isLoading && <div className="flex justify-start"><div className="p-3 bg-gray-700 text-gray-400 italic">Thinking...</div></div>}<div ref={messagesEndRef} />
            </div>
            <div className="flex gap-2">
                <textarea ref={textareaRef} rows={1} value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }} placeholder="תאר את האימון..." className="flex-grow bg-gray-800 text-white p-3 rounded-lg resize-none" dir="rtl" disabled={isLoading} />
                <button onClick={handleSend} disabled={isLoading || !input.trim()} className="px-6 py-3 bg-blue-600 text-white font-semibold rounded-lg">Send</button>
            </div>
        </div>
    );
};


