}

const WorkoutContext = createContext<WorkoutContextType | undefined>(undefined);

export const WorkoutProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { settings } = useSettings();
  const { user, authStatus } = useAuth();
  const { logAction } = useLogger();
  const [plans, setPlans] = useState<WorkoutPlan[]>([]);
  const [activeWorkout, setActiveWorkout] = useState<ActiveWorkout | null>(null);
  const [isWorkoutPaused, setIsWorkoutPaused] = useState(false);
  const [isCountdownPaused, setIsCountdownPaused] = useState(false);
  const [recentlyImportedPlanId, setRecentlyImportedPlanId] = useState<string | null>(null);
  const [workoutHistory, setWorkoutHistory] = useState<WorkoutLogEntry[]>([]);
  const [plansToStart, setPlansToStart] = useState<string[]>([]);
  const [importNotification, setImportNotification] = useState<ImportNotificationData | null>(null);
  const [isSyncing, setIsSyncing] = useState(true);

  const [showGuestMergeModal, setShowGuestMergeModal] = useState(false);
  const [guestPlansToMerge, setGuestPlansToMerge] = useState<WorkoutPlan[]>([]);
  const [guestHistoryToMerge, setGuestHistoryToMerge] = useState<WorkoutLogEntry[]>([]);
  const initialSyncDone = useRef(false);

  const authStatusRef = useRef(authStatus);
  useEffect(() => {
    authStatusRef.current = authStatus;
  }, [authStatus]);

  const isPreparingWorkout = plansToStart.length > 0;

  // Derive currentStep and nextUpcomingStep from activeWorkout
  const currentStep = useMemo(() => {
    if (!activeWorkout) return null;
    return activeWorkout.plan.steps[activeWorkout.currentStepIndex] || null;
  }, [activeWorkout]);

  const nextUpcomingStep = useMemo(() => {
    if (!activeWorkout) return null;
    const nextIndex = activeWorkout.currentStepIndex + 1;
    return activeWorkout.plan.steps[nextIndex] || null;
  }, [activeWorkout]);

  const clearImportNotification = useCallback(() => setImportNotification(null), []);

  const handleFirestoreError = useCallback((error: FirestoreError, context: string) => {
      console.error(`Firestore error in ${context}:`, error);
      logAction(`ERROR_FIRESTORE_${context}`, { message: error.message, code: error.code });
      setIsSyncing(false);
  }, [logAction]);

  // Implement handleMergeGuestData
  const handleMergeGuestData = useCallback(async (options: GuestMergeOptions) => {
      if (!user) return;
      logAction('GUEST_DATA_MERGE_START', options);
      try {
          const batch = writeBatch(db);
          if (options.mergePlans && options.plansToMerge.length > 0) {
              options.plansToMerge.forEach(plan => {
                  const planRef = doc(db, 'users', user.uid, 'plans', plan.id);
                  batch.set(planRef, plan, { merge: true });
              });
          }
          if (options.mergeHistory && guestHistoryToMerge.length > 0) {
              guestHistoryToMerge.forEach(entry => {
                  const historyRef = doc(db, 'users', user.uid, 'history', entry.id);
                  batch.set(historyRef, entry, { merge: true });
              });
          }
          await batch.commit();

          const fingerprint = getGuestDataFingerprint(guestPlansToMerge, guestHistoryToMerge);
          localStorage.setItem(ACK_FINGERPRINT_KEY, fingerprint);

          logAction('GUEST_DATA_MERGE_SUCCESS');
      } catch (error) {
          console.error("Merge failed:", error);
          logAction('ERROR_GUEST_DATA_MERGE', { message: (error as Error).message });
      } finally {
          setShowGuestMergeModal(false);
          setGuestPlansToMerge([]);
          setGuestHistoryToMerge([]);
      }
  }, [user, guestPlansToMerge, guestHistoryToMerge, logAction]);

  // Implement handleDiscardGuestData
  const handleDiscardGuestData = useCallback(() => {
      logAction('GUEST_DATA_DISCARD');
      const fingerprint = getGuestDataFingerprint(guestPlansToMerge, guestHistoryToMerge);
      localStorage.setItem(ACK_FINGERPRINT_KEY, fingerprint);
      setShowGuestMergeModal(false);
      setGuestPlansToMerge([]);
      setGuestHistoryToMerge([]);
  }, [guestPlansToMerge, guestHistoryToMerge, logAction]);

  useEffect(() => {
    let plansUnsubscribe: Unsubscribe | undefined;
    let historyUnsubscribe: Unsubscribe | undefined;

    const cleanup = () => {
        if (plansUnsubscribe) plansUnsubscribe();
        if (historyUnsubscribe) historyUnsubscribe();
        initialSyncDone.current = false;
        setShowGuestMergeModal(false);
        setGuestPlansToMerge([]);
        setGuestHistoryToMerge([]);
    };

    if (authStatus === 'authenticated' && user) {
        logAction('AUTH_STATE_AUTHENTICATED', { uid: user.uid });
        setIsSyncing(true);
        initialSyncDone.current = false;

        let remotePlansCache: WorkoutPlan[] = [];
        let remoteHistoryCache: WorkoutLogEntry[] = [];
        let plansListenerDone = false;
        let historyListenerDone = false;

        const checkAndTriggerMergeModal = () => {
            if (!plansListenerDone || !historyListenerDone || initialSyncDone.current) return;
            initialSyncDone.current = true;
            const localPlans = getLocalPlans().map(migratePlanToV2).filter((p): p is WorkoutPlan => !!p);
            const remotePlanIds = new Set(remotePlansCache.map(p => p.id));
            const newGuestPlans = localPlans.filter(p => !remotePlanIds.has(p.id));
            const localHistory = getLocalHistory();
            const remoteHistoryIds = new Set(remoteHistoryCache.map(h => h.id));
            const newGuestHistory = localHistory.filter(h => !remoteHistoryIds.has(h.id));
            const guestDataFingerprint = getGuestDataFingerprint(newGuestPlans, newGuestHistory);
            const acknowledgedFingerprint = localStorage.getItem(ACK_FINGERPRINT_KEY);
            if (guestDataFingerprint === acknowledgedFingerprint) return;
            if (newGuestPlans.length > 0 || newGuestHistory.length > 0) {
                setGuestPlansToMerge(newGuestPlans);
                setGuestHistoryToMerge(newGuestHistory);
                setShowGuestMergeModal(true);
            }
        };

        const plansCollection = collection(db, 'users', user.uid, 'plans');
        plansUnsubscribe = onSnapshot(query(plansCollection, orderBy('order', 'asc')), (snapshot) => {
            remotePlansCache = snapshot.docs.map(doc => migratePlanToV2(doc.data())).filter((p): p is WorkoutPlan => !!p);
            setPlans(remotePlansCache);
            if (!plansListenerDone) {
                plansListenerDone = true;
                checkAndTriggerMergeModal();
            }
            setIsSyncing(false);
        }, (error) => handleFirestoreError(error, 'PLANS_LISTENER'));

        const historyCollection = collection(db, 'users', user.uid, 'history');
        historyUnsubscribe = onSnapshot(query(historyCollection, orderBy('date', 'desc')), (snapshot) => {
            remoteHistoryCache = snapshot.docs.map(doc => doc.data() as WorkoutLogEntry);
            const remoteHistoryIds = new Set(remoteHistoryCache.map(h => h.id));
            const localHistory = getLocalHistory();
            const localOnlyHistory = localHistory.filter(h => !remoteHistoryIds.has(h.id));
            const combinedHistory = [...remoteHistoryCache, ...localOnlyHistory].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
            setWorkoutHistory(combinedHistory);
            if (!historyListenerDone) {
                historyListenerDone = true;
                checkAndTriggerMergeModal();
            }
        }, (error) => handleFirestoreError(error, 'HISTORY_LISTENER'));

    } else if (authStatus === 'unauthenticated') {
        cleanup();
        setPlans(getLocalPlans().map(migratePlanToV2).filter((p): p is WorkoutPlan => !!p));
        setWorkoutHistory(getLocalHistory());
        setActiveWorkout(null);
        setIsSyncing(false);
    }
    return cleanup;
  }, [user, authStatus, logAction, handleFirestoreError]);

  const savePlan = useCallback(async (planToSave: WorkoutPlan) => {
      logAction('PLAN_SAVE_ATTEMPT', { planId: planToSave.id, planName: planToSave.name });
      const migratedPlan = migratePlanToV2(planToSave);
      if (!migratedPlan) return;

      // Preparation: Calculate order outside the state setter to ensure Firestore gets it.
      const isNewPlan = !plans.some(p => p.id === migratedPlan.id);
      if (isNewPlan && migratedPlan.order === undefined) {
          const maxOrder = plans.reduce((max, p) => Math.max(max, p.order ?? -1), -1);
          migratedPlan.order = maxOrder + 1;
      }

      // 1. Update local state
      setPlans(prevPlans => {
          let newPlans;
          const exists = prevPlans.some(p => p.id === migratedPlan.id);
          if (!exists) {
              newPlans = [...prevPlans, migratedPlan];
          } else {
              newPlans = prevPlans.map(p => p.id === migratedPlan.id ? migratedPlan : p);
          }
          // Sort locally to match Firestore's order logic
          newPlans.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

          // 2. Always update local storage as a cache/fallback
          saveLocalPlans(newPlans);
          return newPlans;
      });

      // 3. Sync to Cloud
      if (user) {
          try {
              const planRef = doc(db, 'users', user.uid, 'plans', migratedPlan.id);
              // Send the full migratedPlan object including the newly calculated order.
              await setDoc(planRef, migratedPlan, { merge: true });
              logAction('PLAN_SAVE_FIRESTORE_SUCCESS', { planId: migratedPlan.id });
          } catch (error) {
              logAction('ERROR_PLAN_SAVE_FIRESTORE', { planId: migratedPlan.id, message: (error as Error).message });
              console.error("Failed to save plan to Firestore:", error);
          }
      }
  }, [user, plans, logAction]);

  const importPlan = useCallback((planToImport: WorkoutPlan, source: string = 'file') => {
    logAction('PLAN_IMPORT_ATTEMPT', { planName: planToImport.name, source });
    const migratedPlan = migratePlanToV2(planToImport);
    if (!migratedPlan) return;

    const isDuplicate = plans.some(existingPlan => arePlansDeeplyEqual(migratedPlan, existingPlan));
    if (isDuplicate) {
        setImportNotification({ message: 'האימון כבר קיים', planName: `"${migratedPlan.name}" לא יובא שוב.`, type: 'warning' });
        return;
    }

    const newPlanId = `${Date.now()}_imported_from_${source}`;
    const newPlan: WorkoutPlan = {
      ...migratedPlan,
      id: newPlanId,
      version: 2,
      steps: migratedPlan.steps.map((step, index) => ({
        ...step,
        id: `${Date.now()}_imported_step_${index}`
      }))
    };

    if (source === 'ai') {
        newPlan.isSmartPlan = true;
        newPlan.color = '#a855f7';
        newPlan.steps = processAndFormatAiSteps(newPlan.steps);
        newPlan.steps = newPlan.steps.map(step => {
            if (step.type === 'exercise' && !step.isRepBased && (!step.duration || step.duration <= 0)) {
                return { ...step, isRepBased: true, reps: 10, duration: 0 };
            }
            return step;
        });
    }

    savePlan(newPlan);
    setImportNotification({ message: 'תוכנית אימונים יובאה בהצלחה!', planName: newPlan.name, type: 'success' });
    prefetchExercises(newPlan.steps.filter(s => s.type === 'exercise').map(s => s.name));
    setRecentlyImportedPlanId(newPlanId);
    setTimeout(() => setRecentlyImportedPlanId(null), 2500);
  }, [savePlan, plans, logAction]);

  const deletePlan = useCallback(async (planId: string) => {
    logAction('PLAN_DELETE_ATTEMPT', { planId });
    if (user) {
        try {
            const planRef = doc(db, 'users', user.uid, 'plans', planId);
            await deleteDoc(planRef);
        } catch (error) {
            handleFirestoreError(error as FirestoreError, 'PLAN_DELETE');
        }
    } else {
        const newPlans = plans.filter(p => p.id !== planId);
        setPlans(newPlans);
        saveLocalPlans(newPlans);
    }
  }, [user, plans, logAction, handleFirestoreError]);

  const reorderPlans = useCallback(async (reorderedPlans: WorkoutPlan[]) => {
      logAction('PLANS_REORDERED', { count: reorderedPlans.length });
      const plansWithOrder = reorderedPlans.map((p, i) => ({ ...p, order: i }));
      setPlans(plansWithOrder);
      saveLocalPlans(plansWithOrder);

      if (user) {
        try {
            const batch = writeBatch(db);
            plansWithOrder.forEach((plan) => {
                const planRef = doc(db, 'users', user.uid, 'plans', plan.id);
                batch.set(planRef, plan, { merge: true });
            });
            await batch.commit();
        } catch (error) {
            handleFirestoreError(error as FirestoreError, 'PLANS_REORDER');
        }
      }
  }, [user, logAction, handleFirestoreError]);

  const value = {
    plans,
    activeWorkout,
    currentStep,
    nextUpcomingStep,
    isWorkoutPaused,
    isCountdownPaused,
    recentlyImportedPlanId,
    workoutHistory,
    isPreparingWorkout,
    isSyncing,
    importNotification,
    showGuestMergeModal,
    guestPlansToMerge,
    guestHistoryToMerge,
    handleMergeGuestData,
    handleDiscardGuestData,
    clearImportNotification,
    savePlan,
    importPlan,
    deletePlan,
    reorderPlans,
    startWorkout: (planIds: string[]) => { setPlansToStart(planIds); },
    commitStartWorkout: () => {
        if (plansToStart.length === 0) return;
        const plansToRun = plansToStart.map(id => plans.find(p => p.id === id)).filter(Boolean) as WorkoutPlan[];
        if (plansToRun.length === 0) { setPlansToStart([]); return; }
        const executionMode = plansToRun.length === 1 ? (plansToRun[0].executionMode || 'linear') : 'linear';
        let mainWorkoutSteps = plansToRun.flatMap(p => p.steps);
        if (executionMode === 'circuit') mainWorkoutSteps = generateCircuitSteps(mainWorkoutSteps);
        let allSteps: WorkoutStep[] = [];
        if (settings.isWarmupEnabled && settings.warmupSteps.length > 0) {
            const enabledWarmupSteps = settings.warmupSteps.filter(step => step.enabled !== false);
            allSteps.push(...enabledWarmupSteps.map(step => ({ ...step, isWarmup: true })));
            if (settings.restAfterWarmupDuration > 0 && enabledWarmupSteps.length > 0) {
                allSteps.push({ id: `rest_after_warmup_${Date.now()}`, name: 'מנוחה לפני אימון', type: 'rest', isRepBased: false, duration: settings.restAfterWarmupDuration, reps: 0, isWarmup: true });
            }
        }
        allSteps.push(...mainWorkoutSteps);
        if (allSteps.length === 0) { setPlansToStart([]); return; }
        const metaPlan: WorkoutPlan = { id: `meta_${Date.now()}`, name: plansToRun.map(p => p.name).join(' & '), steps: allSteps, executionMode, version: 2 };
        setActiveWorkout({ plan: metaPlan, currentStepIndex: 0, sourcePlanIds: plansToStart, stepRestartKey: 0, sessionLog: [], stepStartTime: Date.now() });
        setIsWorkoutPaused(false);
        setIsCountdownPaused(false);
        setPlansToStart([]);
    },
    clearPreparingWorkout: () => { setPlansToStart([]); },
    stopWorkout: ({ completed, durationMs, finishedWorkout }: { completed: boolean; durationMs: number; finishedWorkout: ActiveWorkout }) => {
        if (completed) {
            const finalSessionLog = [...finishedWorkout.sessionLog];
            const lastStep = finishedWorkout.plan.steps[finishedWorkout.currentStepIndex];
            if (lastStep) finalSessionLog.push({ step: lastStep, status: StepStatus.Completed, durationMs: Date.now() - finishedWorkout.stepStartTime });
            const now = new Date();
            const newEntry: WorkoutLogEntry = { id: now.toISOString(), date: now.toISOString(), planName: finishedWorkout.plan.name, durationSeconds: Math.round(durationMs / 1000), steps: finishedWorkout.plan.steps, planIds: finishedWorkout.sourcePlanIds, performedSteps: finalSessionLog };
            if (user) setDoc(doc(db, 'users', user.uid, 'history', newEntry.id), newEntry).catch(e => console.error(e));
            else { setWorkoutHistory(prev => { const h = [newEntry, ...prev]; saveLocalHistory(h); return h; }); }
        }
        setActiveWorkout(null);
        setIsWorkoutPaused(false);
        setIsCountdownPaused(false);
    },
    nextStep: (timestamp: number, status: StepStatus) => {
        setActiveWorkout(prev => {
            if (!prev) return null;
            const currentStep = prev.plan.steps[prev.currentStepIndex];
            const performedStep = { step: currentStep, status, durationMs: timestamp - prev.stepStartTime };
            const newSessionLog = [...prev.sessionLog, performedStep];
            if (prev.currentStepIndex + 1 >= prev.plan.steps.length) return null;
            return { ...prev, currentStepIndex: prev.currentStepIndex + 1, sessionLog: newSessionLog, stepStartTime: timestamp };
        });
        setIsCountdownPaused(false);
    },
    previousStep: (timestamp: number) => {
        setActiveWorkout(prev => {
            if (!prev || prev.currentStepIndex === 0) return prev;
            const newSessionLog = prev.sessionLog.slice(0, -1);
            const lastDur = newSessionLog.length > 0 ? newSessionLog[newSessionLog.length - 1].durationMs : 0;
            return { ...prev, currentStepIndex: prev.currentStepIndex - 1, sessionLog: newSessionLog, stepStartTime: timestamp - lastDur };
        });
        setIsCountdownPaused(false);
    },
    pauseWorkout: () => setIsWorkoutPaused(true),
    resumeWorkout: () => setIsWorkoutPaused(false),
    restartWorkout: () => { setActiveWorkout(prev => prev ? { ...prev, currentStepIndex: 0, stepRestartKey: (prev.stepRestartKey || 0) + 1, sessionLog: [], stepStartTime: Date.now() } : null); setIsWorkoutPaused(false); setIsCountdownPaused(false); },
    pauseStepCountdown: () => setIsCountdownPaused(true),
    resumeStepCountdown: () => setIsCountdownPaused(false),
    restartCurrentStep: () => { setActiveWorkout(prev => prev ? { ...prev, stepRestartKey: (prev.stepRestartKey || 0) + 1, stepStartTime: Date.now() } : null); setIsCountdownPaused(false); },
    clearWorkoutHistory: () => {
        if (window.confirm("Are you sure?")) {
            if (user) {
                getDocs(collection(db, 'users', user.uid, 'history')).then(snap => {
                    const batch = writeBatch(db);
                    snap.forEach(d => batch.delete(d.ref));
                    batch.commit();
                });
            } else {
                setWorkoutHistory([]);
                saveLocalHistory([]);
            }
        }
    },
    forceSync: () => { if (user) setIsSyncing(true); },
    logManualSession: (name: string, durationMs: number, performedSteps: PerformedStep[]) => {
        const now = new Date();
        const entry = { id: now.toISOString(), date: now.toISOString(), planName: name, durationSeconds: Math.round(durationMs / 1000), steps: performedSteps.map(p => p.step), planIds: ['manual_session'], performedSteps };
        if (user) setDoc(doc(db, 'users', user.uid, 'history', entry.id), entry).catch(e => console.error(e));
        else { setWorkoutHistory(prev => { const h = [entry, ...prev]; saveLocalHistory(h); return h; }); }
    }
  };

  return <WorkoutContext.Provider value={value}>{children}</WorkoutContext.Provider>;
};

export const useWorkout = (): WorkoutContextType => {
  const context = useContext(WorkoutContext);
  if (context === undefined) {
    throw new Error('useWorkout must be used within a WorkoutProvider');
  }
  return context;
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { useLogger } from '../contexts/LoggingContext';

const CRASH_FLAG_KEY = 'app_crash_detected';

interface Props {
  children: ReactNode;
  logError: (error: Error, componentStack: string) => void;
}

interface State {
  hasError: boolean;
}

// Fixed ErrorBoundaryInternal by ensuring React.Component is correctly inherited and typed
class ErrorBoundaryInternal extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  public static getDerivedStateFromError(_: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
    this.props.logError(error, errorInfo.componentStack);
    // Set a flag in localStorage so we can detect this crash on the next app load.
    try {
        localStorage.setItem(CRASH_FLAG_KEY, 'true');
    } catch (e) {
        console.error("Could not set crash flag in localStorage:", e);
    }
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen w-screen bg-red-900 text-white flex flex-col items-center justify-center p-4 text-center">
            <h1 className="text-4xl font-bold">התרחשה שגיאה</h1>
            <p className="mt-4 text-lg">אפליקציית השעון נתקלה בבעיה בלתי צפויה.</p>
            <p className="mt-2 text-md text-red-200">
                נסה לרענן את הדף. אם הבעיה נמשכת, אנא פתח את תפריט ההגדרות, עבור לקטע 'מפתחים' והעתק את פרטי ניפוי השגיאות כדי לדווח על הבעיה.
            </p>
            <button
                onClick={() => window.location.reload()}
                className="mt-8 px-6 py-3 bg-red-600 rounded-lg font-semibold hover:bg-red-700 transition-colors"
            >
                רענן דף
            </button>
        </div>
      );
    }

    return this.props.children;
  }
}

// Wrapper component to inject the logger context function into the class component
export const ErrorBoundary: React.FC<{children: ReactNode}> = ({ children }) => {
    const { logError } = useLogger();
    // Explicitly pass children as a prop to satisfy TypeScript validation
    return <ErrorBoundaryInternal logError={logError}>{children}</ErrorBoundaryInternal>;
};

import { useState, useEffect, useCallback } from 'react';
import { WorkoutStep } from '../types';
import { getLocalSettings, saveLocalSettings } from '../services/storageService';
import { useLogger } from '../contexts/LoggingContext';

export interface CustomSound {
  name: string;
  dataUrl: string;
}

export interface Settings {
  showTimer: boolean;
  showCountdown: boolean;
  showCycleCounter: boolean;
  stealthModeEnabled: boolean;
  countdownDuration: number;
  countdownRestDuration: number;
  allSoundsEnabled: boolean;
  playSoundAtHalfway: boolean;
  playSoundAtEnd: boolean;
  playSoundOnRestart: boolean;
  volume: number;
  isMuted: boolean;
  countdownSize: number;
  stopwatchSize: number;
  countdownControlsSize: number;
  stopwatchControlsSize: number;
  showCountdownControls: boolean;
  showStopwatchControls: boolean;
  defaultExerciseDuration: number;
  defaultRestDuration: number;
  showNextExercise: boolean;
  backgroundColor: string;
  halfwayColor: string;
  restBackgroundColor: string;
  showRestTitleOnDefaultCountdown: boolean;
  preWorkoutCountdownDuration: number;
  settingsCategoryOrder: string[];
  customSounds?: {
    start?: CustomSound;
    end?: CustomSound;
    notification?: CustomSound;
    tick?: CustomSound;
  };
  isWarmupEnabled: boolean;
  warmupSteps: WorkoutStep[];
  restAfterWarmupDuration: number;
  showLogSessionButton: boolean;
  keepScreenOnDuringWorkout: boolean;
  userProfile?: {
    birthDate?: string; // ISO string like "YYYY-MM-DD"
    fitnessLevel?: 'beginner' | 'intermediate' | 'advanced';
    equipment?: { name: string; available: boolean }[];
  };
}

const defaultSettings: Settings = {
  showTimer: true,
  showCountdown: true,
  showCycleCounter: true,
  stealthModeEnabled: false,
  countdownDuration: 40,
  countdownRestDuration: 3,
  allSoundsEnabled: true,
  playSoundAtHalfway: true,
  playSoundAtEnd: true,
  playSoundOnRestart: true,
  volume: 0.5,
  isMuted: false,
  countdownSize: 100,
  stopwatchSize: 100,
  countdownControlsSize: 100,
  stopwatchControlsSize: 100,
  showCountdownControls: true,
  showStopwatchControls: true,
  defaultExerciseDuration: 40,
  defaultRestDuration: 20,
  showNextExercise: true,
  backgroundColor: '#000000',
  halfwayColor: '#FF0000',
  restBackgroundColor: '#FFFFFF',
  showRestTitleOnDefaultCountdown: true,
  preWorkoutCountdownDuration: 10,
  settingsCategoryOrder: ['sounds', 'customSounds', 'countdown', 'stopwatch', 'workoutDisplay', 'displaySizes', 'displayColors', 'developer'],
  customSounds: {},
  isWarmupEnabled: false,
  warmupSteps: [],
  restAfterWarmupDuration: 15,
  showLogSessionButton: true,
  keepScreenOnDuringWorkout: true,
  userProfile: {
    birthDate: '',
    fitnessLevel: 'intermediate',
    equipment: [
      { name: 'Dumbbells', available: true },
      { name: 'Resistance Bands', available: false },
      { name: 'Yoga Mat', available: true },
    ],
  },
};

const getInitialSettings = (): Settings => {
  const localSettings = getLocalSettings();
  // Ensure the developer category is present for existing users
  if (localSettings && !localSettings.settingsCategoryOrder?.includes('developer')) {
    localSettings.settingsCategoryOrder = [...(localSettings.settingsCategoryOrder || defaultSettings.settingsCategoryOrder), 'developer'];
  }
  // Ensure the customSounds category is present for existing users
  if (localSettings && !localSettings.settingsCategoryOrder?.includes('customSounds')) {
      const soundsIndex = localSettings.settingsCategoryOrder?.indexOf('sounds') ?? -1;
      if (soundsIndex > -1) {
          localSettings.settingsCategoryOrder?.splice(soundsIndex + 1, 0, 'customSounds');
      } else {
          localSettings.settingsCategoryOrder = [
              'sounds', 
              'customSounds', 
              ...(localSettings.settingsCategoryOrder || defaultSettings.settingsCategoryOrder)
          ];
      }
  }
  return localSettings ? { ...defaultSettings, ...localSettings } : defaultSettings;
};

export const useSettings = () => {
  const [settings, setSettings] = useState<Settings>(getInitialSettings);
  const { logAction } = useLogger();

  useEffect(() => {
    saveLocalSettings(settings);
  }, [settings]);

  const updateSettings = useCallback((newSettings: Partial<Settings>) => {
    logAction('SETTINGS_UPDATED', newSettings);
    setSettings(prevSettings => ({ ...prevSettings, ...newSettings }));
  }, [logAction]);

  return { settings, updateSettings };
};

