  const { logAction } = useLogger();
  useEffect(() => {
    logAction('APP_MOUNTED', { userAgent: navigator.userAgent });
  }, [logAction]);

  return <AppContent />;
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <LoggingProvider>
        <SettingsProvider>
          <WorkoutProvider>
            <ErrorBoundary>
              <AppWithLogging />
            </ErrorBoundary>
          </WorkoutProvider>
        </SettingsProvider>
      </LoggingProvider>
    </AuthProvider>
  );
};

export default App;

